import {costCatalog,catalogChildren,categoryPath,changeCostCategory,COST_NATURES,UNITS} from './cost-catalog.js';
import {buildCostHierarchy,costHierarchySummary,costBreakdown,allocatedCostLines} from './cost-analytics.js';
import {uid,paise,qtyScaled,lineTotal,lineValue,billTotal,displayMoney,inputMoney,sum,emptyState,verifyState,dueForBill,dueForPlan,availableForPayment,summary,breakdown,breakdownDetailed,monthlyTotals,eventList,localDate,localStamp,makeBill,checkNewPayment,changeEntry,validDate} from './finance.js';
import {readState,modify,readFile,openDb,storageMode,loginRemote,hasPendingWrite,retryPendingWrite} from './db.js';import {buildHierarchy,hierarchySummary} from './hierarchy.js';import {createBackup,restoreBackup,downloadBlob} from './archive.js';
const $=id=>document.getElementById(id), escapeHTML=x=>String(x??'').replace(/[&<>"']/g,k=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[k]));
const pages=[['home','⌂','Home'],['add','⊞','Add Entry'],['activity','◷','Activity'],['files','▤','Files'],['explore','▥','Explore']];const colors=['#17665a','#628e80','#a8bcb1','#d2b988','#8196a3','#a8867b','#c8d2d0'];
const workOptions=['Sump & excavation','Footing & plinth','Columns & RCC','Masonry & plaster','Electrical','Plumbing & sanitary','Flooring & tiles','Doors & windows','Painting & finishing','Kitchen & interiors','Lift & solar','Labour & contractors','Engineering & design','General / other'];
const recommendedSubstages=['Excavation','Soil disposal','PCC','Reinforcement','Formwork / shuttering','RCC casting','Footings','Plinth beam','Masonry','Plastering','Waterproofing','Pipe laying','Basins and commodes','Conduits','Wiring','Switches','Light fixtures','Floor tiling','Doors installation','Site inspection'];
const fileCategories=['Architectural drawings','Structural drawings','Sump and underground','Survey / CAD','Lift and equipment','MEP drawings','Bills and proof','Agreements','Site photographs','Approvals','Warranties','Miscellaneous'];
let state=emptyState(),route='home',flow=null,selectedView='cost',costPath=[],costSearch='',categoryMode='cost',categorySearch='',hierarchyPath=[],hierarchyLimit=30,fileFilter='All',activityFilter='All',activitySearch='',activityFrom='',activityTo='',month=new Date().getMonth(),year=new Date().getFullYear(),calendarDay=localDate(),modalURL=null,noticeShown=new Set();let bc;
function toast(msg,bad=false){const el=$('toast');el.textContent=msg;el.style.background=bad?'#963d47':'#243d50';el.classList.add('show');clearTimeout(toast.timeout);toast.timeout=setTimeout(()=>el.classList.remove('show'),4500)}
async function refresh(){state=await readState();$('project-name').textContent=state.project.name;render()}
async function commit(callback,options={}){
 try{const r=await modify(callback,options);try{await refresh()}catch{toast('Saved successfully. Refresh to reload the latest totals.',true)}return r}
 catch(e){if(e.code==='SAVE_UNCERTAIN'){pending=null;closeModal();showPendingSave()}throw e}
}
function showPendingSave(){if(!hasPendingWrite())return;const main=$('main');if(!main.querySelector('#pending-save'))main.insertAdjacentHTML('afterbegin',`<div id="pending-save" class="notice warn" role="alert"><strong>A save needs verification.</strong> Retry the original save before adding or editing entries. ${btn('retry-save','Retry save','btn small')}</div>`)}
function navHTML(){const html=pages.map(([id,ico,label])=>`<button class="nav-item ${route===id?'active':''}" data-nav="${id}" ${route===id?'aria-current="page"':''}><span class="navicon" aria-hidden="true">${ico}</span><span>${label}</span></button>`).join('');$('rail-nav').innerHTML=html;$('bottom-nav').innerHTML=html}
function goto(page){route=page;flow=null;navHTML();render();window.scrollTo(0,0)}function heading(name,desc,action=''){return `<div class="page-head"><div><h1>${name}</h1><p>${desc}</p></div>${action}</div>`}
function btn(action,text,klass='btn',extras=''){return `<button class="${klass}" data-action="${action}" ${extras}>${text}</button>`}
function lineBar(label,value,max,index,drill=''){return `<div class="barrow">${drill?`<button class="chart-click" data-drill="${escapeHTML(drill)}" data-value="${escapeHTML(label)}">`:''}<div class="barlabels"><span>${escapeHTML(label)}</span><strong>${displayMoney(value)}</strong></div><div class="track"><div class="fill" style="background:${colors[index%colors.length]};width:${Math.max(0,Math.min(100,100*value/Math.max(1,max)))}%"></div></div>${drill?'</button>':''}</div>`}
function workBars(mode='work',drill=false){const dat=breakdown(state,mode);if(!dat.length)return `<div class="empty"><strong>Nothing recorded yet</strong>Add a purchase or bill to see the breakdown.</div>`;return (drill?dat:dat.slice(0,6)).map(([name,val],i)=>lineBar(name,val,dat[0][1],i,drill?mode:'')).join('')}
function compactLabel(mode){return mode==='work'?'work stages':mode==='place'?'locations':mode==='vendor'?'suppliers':'materials'}
function segmentDonut(mode='work'){const info=breakdownDetailed(state,mode,5);if(!info.total)return `<div class="empty"><strong>No infographic yet</strong>Once you record bills, this section will group them by ${compactLabel(mode)}.</div>`;let start=0;const stops=[];info.segments.forEach((seg,i)=>{const from=(start*100).toFixed(2),to=((start+seg.share)*100).toFixed(2);stops.push(`${colors[i%colors.length]} ${from}% ${to}%`);start+=seg.share});const style=`background:conic-gradient(${stops.join(',')})`;return `<div class="seg-layout"><div class="seg-donut-wrap"><div class="seg-donut" style="${style}"><div class="seg-donut-hole"><small>Total cost</small><strong>${displayMoney(info.total)}</strong><span>${info.categoryCount} ${compactLabel(mode)}</span></div></div></div><div class="seg-legend">${info.segments.map((seg,i)=>`<button class="seg-card" data-drill="${escapeHTML(mode)}" data-value="${escapeHTML(seg.name)}"><span class="seg-chip" style="background:${colors[i%colors.length]}"></span><span class="seg-copy"><strong>${escapeHTML(seg.name)}</strong><small>${(seg.share*100).toFixed(1)}% · ${displayMoney(seg.value)}</small></span></button>`).join('')}</div></div>`}
function segmentSnapshot(mode='work'){const info=breakdownDetailed(state,mode,5);const focus=info.largest?Math.round(info.largest.share*100):0;return `<div class="snapshot-grid">${[['Largest segment',info.largest?info.largest.name:'—',info.largest?`${displayMoney(info.largest.value)} · ${focus}% of recorded cost`:'No data yet'],['Coverage',`${Math.max(0,100-Math.round((info.uncategorised/Math.max(1,info.total))*100))}% categorised`,info.uncategorised?`${displayMoney(info.uncategorised)} still needs cleaner labels`:'Everything currently has a category'],['Spread',`${info.categoryCount||0} categories`,info.otherValue?`${displayMoney(info.otherValue)} sits outside the top groups`:'Most of your cost is already visible in the top groups']].map(([k,v,d])=>`<div class="snapshot-card"><small>${k}</small><strong>${escapeHTML(v)}</strong><span>${escapeHTML(d)}</span></div>`).join('')}</div>`}
function activityRows(events){
 if(!events.length)return `<div class="empty"><strong>No matching activity</strong>Try another search or date range.</div>`;
 return events.map(e=>`<button class="list-row activity-row" data-detail="${escapeHTML(e.kind)}:${escapeHTML(e.id)}"><span class="event-mark ${e.kind==='audit'?'log-mark':''}" aria-hidden="true">${({bill:'\u2199',payment:'\u2197',plan:'\u25f7',file:'\u25a4',contract:'=',audit:'\u00b7',note:'='})[e.kind]||'\u00b7'}</span><span class="event-copy"><strong>${escapeHTML(e.label)}</strong><small>${escapeHTML(e.party||e.work||'Project')} \u00b7 ${escapeHTML(localStamp(e.at))}</small><small>${escapeHTML(e.status)}${e.date?' \u00b7 '+escapeHTML(e.date):''}</small></span><span class="event-end">${e.amount==null?'<span class="tag">Change log</span>':`<strong class="amount">${displayMoney(e.amount)}</strong><small>${escapeHTML(e.kind)}</small>`}</span></button>`).join('');
}
function home(){
 const x=summary(state),today=localDate();
 const dueBills=state.bills.map(b=>({b,due:dueForBill(state,b.id)})).filter(x=>x.due>0).sort((a,b)=>b.due-a.due);
 const plans=state.plans.filter(p=>!p.cancelled&&dueForPlan(state,p.id)>0).sort((a,b)=>a.due.localeCompare(b.due));
 const used=x.budget?Math.min(100,x.invoiced/x.budget*100):0;
 return `${heading('Project overview','Your construction finances, clearly accounted for.',`<div class="actions">${btn('calendar','Payment calendar')}${btn('add','+ New entry','btn primary')}</div>`)}<div class="kpis"><button class="kpi hero" data-nav="activity" data-filter="payment"><span class="k">Money paid</span><strong>${displayMoney(x.paid)}</strong><span class="sub">Actual cash outflow <span aria-hidden="true">\u2197</span></span></button><button class="kpi" data-nav="activity" data-filter="bill"><span class="k">Recorded cost</span><strong>${displayMoney(x.invoiced)}</strong><span class="sub">${state.bills.length} supplier bills <span aria-hidden="true">\u2197</span></span></button><button class="kpi" data-nav="activity" data-filter="bill"><span class="k">Outstanding bills</span><strong>${displayMoney(x.owed)}</strong><span class="sub">${dueBills.length} awaiting settlement <span aria-hidden="true">\u2197</span></span></button><button class="kpi" data-action="calendar"><span class="k">Next 30 days</span><strong>${displayMoney(x.planned)}</strong><span class="sub">Scheduled payments <span aria-hidden="true">\u2197</span></span></button></div><p class="info-note">Bills recorded: <strong>${displayMoney(x.invoiced)}</strong> ? Unapplied advances: <strong>${displayMoney(x.advances)}</strong>. Plans may overlap unpaid bills; do not add them together.</p><div class="dashboard-grid"><section class="card"><div class="section-head"><div><span class="eyebrow">CASH FLOW</span><h2>Payments over time</h2></div><span class="tag">Last 12 recorded months</span></div>${monthlyChart()}</section><section class="card budget-card"><span class="eyebrow">PROJECT BUDGET</span><h2>${x.budget?displayMoney(x.budget):'Set your budget'}</h2><p class="mini">Recorded bills against your project budget.</p><div class="budget-meter" role="img" aria-label="${x.budget?Math.round(x.invoiced/x.budget*100)+' percent of budget recorded':'Budget not set'}"><span style="width:${used}%"></span></div><div class="budget-numbers"><strong>${x.budget?Math.round(x.invoiced/x.budget*100)+'%':'\u2014'}</strong><span>${x.budget?displayMoney(Math.abs(x.budget-x.invoiced))+(x.invoiced>x.budget?' over budget':' remaining'):'Add a budget to track remaining funds'}</span></div>${btn('settings','Edit project budget','btn small')}</section></div><div class="two section"><section class="card"><div class="section-head"><div><span class="eyebrow">COST DISTRIBUTION</span><h2>Where the cost went</h2></div>${btn('explore','Explore costs \u2192','btn link')}</div>${costBars('head',6)}</section><section class="card"><div class="section-head"><div><span class="eyebrow">UP NEXT</span><h2>Payments to watch</h2></div>${btn('calendar','View calendar \u2192','btn link')}</div>${plans.slice(0,3).map(p=>`<button class="list-row" data-detail="plan:${escapeHTML(p.id)}"><span><strong>${escapeHTML(p.title)}</strong><small>${escapeHTML(p.vendor)} \u00b7 ${escapeHTML(p.due)}${p.due<today?' ? Overdue':''}</small></span><span class="amount">${displayMoney(dueForPlan(state,p.id))}</span></button>`).join('')}${dueBills.slice(0,Math.max(1,4-plans.length)).map(({b,due})=>`<button class="list-row" data-detail="bill:${escapeHTML(b.id)}"><span><strong>${escapeHTML(b.vendor)}</strong><small>${escapeHTML(b.title)} ? Unpaid bill</small></span><span class="amount">${displayMoney(due)}</span></button>`).join('')}${!plans.length&&!dueBills.length?'<div class="empty"><strong>Everything is up to date</strong>No unpaid bills or scheduled payments.</div>':''}</section></div><section class="card section"><div class="section-head"><div><span class="eyebrow">PROJECT JOURNAL</span><h2>Recent activity & changes</h2></div>${btn('activity','View all activity \u2192','btn link')}</div>${activityRows(eventList(state).slice(0,6))}</section>`;
}
function addHome(){const choices=[['purchase','▧','Bought materials','Enter the total directly or calculate by quantity'],['payment','₹','Paid someone','Bill settlement or supplier advance'],['labour','♧','Labour or work','Wages, contractor or service'],['other','◈','Other expense','Transport, fees, hire, utilities'],['bill','▤','Received a bill','Record now, pay later'],['plan','▦','Plan a payment','Instalment, due date, reminder'],['contract','≡','Contract & instalments','Engineer and contractor agreements'],['allocate','↔','Apply an advance','Use existing advance on a bill'],['note','◷','Work log / timer','Site visit, notes, clocked time']];return `${heading('Add Entry','Choose what happened. Only the relevant fields will appear.')}<div class="entry-grid">${choices.map(([key,ico,name,desc])=>`<button class="entry-choice" data-flow="${key}"><span class="sym">${ico}</span><strong>${name}</strong><small>${desc}</small></button>`).join('')}</div><p class="notice section"><b>Keeping figures correct:</b> A new bill records a cost. A payment records money leaving. A planned instalment is not money paid. The application keeps them separate.</p>`}
const field=(id,label,opts={})=>{const full=opts.full?' full':'',hint=opts.hint?`<small class="hint">${escapeHTML(opts.hint)}</small>`:'',req=opts.required?'required':'',val=opts.value??'',placeholder=opts.placeholder||'';let control=opts.options?`<select name="${id}" id="f-${id}" ${req}>${opts.options.map(x=>`<option value="${escapeHTML(Array.isArray(x)?x[0]:x)}">${escapeHTML(Array.isArray(x)?x[1]:x)}</option>`).join('')}</select>`:opts.type==='textarea'?`<textarea name="${id}" id="f-${id}" placeholder="${escapeHTML(placeholder)}"></textarea>`:`<input name="${id}" id="f-${id}" type="${opts.type||'text'}" value="${escapeHTML(val)}" placeholder="${escapeHTML(placeholder)}" ${req} ${opts.extra||''}>`;return `<div class="field${full}"><label for="f-${id}">${escapeHTML(label)}${opts.required?' *':''}</label>${control}${hint}</div>`};
function customCatalog(){return Array.isArray(state.settings?.catalog)?state.settings.catalog:[]}
function stageOptions(){return [...new Set([...workOptions,...customCatalog().map(c=>c.stage).filter(Boolean)])].sort((a,b)=>a.localeCompare(b))}
function substageDataList(){return `<datalist id="stage-substage-choices">${[...new Set([...recommendedSubstages,...customCatalog().map(c=>c.substage).filter(Boolean)])].map(x=>`<option value="${escapeHTML(x)}"></option>`).join('')}</datalist>`}
const workField=()=>field('work','Work stage (optional)',{options:[['','Not specified'],...stageOptions()]});const dateField=()=>field('date','Date',{type:'date',value:localDate(),required:true});const amountField=(label='Amount (₹)')=>field('amount',label,{type:'number',required:true,extra:'min="0.01" step="0.01"'});
function classificationFields(record={}){const catalog=costCatalog(state);const selector=(key,label,parent)=>`<label>${label}<select class="cost-select" data-cost="${key}"><option value="">${key==='costHeadId'?'Unclassified / Legacy':'Not specified'}</option>${catalogChildren(catalog,parent,{activeOnly:false}).filter(n=>n.active!==false||n.id===record[key]).map(n=>`<option value="${escapeHTML(n.id)}" ${n.id===record[key]?'selected':''}>${escapeHTML(n.label)}${n.active===false?' (inactive)':''}</option>`).join('')}</select></label>`;return `<div class="cost-fields line-grid">${selector('costHeadId','Cost head',null)}${record.costHeadId?selector('costSubheadId','Subhead',record.costHeadId):selector('costSubheadId','Subhead','__none')}${record.costSubheadId?selector('costDetailId','Item / service',record.costSubheadId):selector('costDetailId','Item / service','__none')}<label>Cost nature<select data-cost="costNature"><option value="">Not specified</option>${COST_NATURES.map(n=>`<option ${record.costNature===n?'selected':''}>${escapeHTML(n)}</option>`).join('')}</select></label></div>`}
function readClassificationData(record){return Object.fromEntries(['costHeadId','costSubheadId','costDetailId','costNature'].map(k=>[k,record[k]||null]))}
function readClassification(container){return Object.fromEntries(['costHeadId','costSubheadId','costDetailId','costNature'].map(k=>[k,container.querySelector(`[data-cost="${k}"]`)?.value||null]))}
function updateClassification(target){const row=target.closest('[data-line]'),box=target.closest('.cost-fields'),record=readClassification(box),catalog=costCatalog(state);if(target.dataset.cost==='costHeadId'){record.costSubheadId=null;record.costDetailId=null}if(target.dataset.cost==='costSubheadId')record.costDetailId=null;const key=target.dataset.cost,parent=box.parentElement;box.outerHTML=classificationFields(record);parent.querySelector(`[data-cost="${key}"]`)?.focus();{const node=catalog.find(n=>n.id===(record.costDetailId||record.costSubheadId));const unit=row?.querySelector('.item-unit')||$('f-unitId');if(unit&&node?.suggestedUnit)unit.value=node.suggestedUnit}}
function unitOptions(){return `<option value="">Choose unit (optional)</option>${UNITS.map(u=>`<option value="${u.id}">${escapeHTML(u.label)}</option>`).join('')}`}
function costBars(key='head',limit=Infinity){const rows=costBreakdown(state,key);return rows.slice(0,limit).map(([name,value],i)=>lineBar(name,value,rows[0]?.[1]||1,i)).join('')||'<div class="empty">No recorded costs.</div>'}
function advancedCalculationFields(){return `<details class="field full"><summary class="extras-title">Advanced calculation (optional)</summary><div class="grid-form">${field('calculate','Amount method',{options:[['amount','Use direct amount'],['calculated','Quantity x rate']]})}${field('calcQty','Quantity',{extra:'inputmode="decimal"'})}${field('calcRate','Rate (INR)',{extra:'inputmode="decimal"'})}${field('unitId','Rate unit',{options:[['','Choose rate unit (optional)'],...UNITS.filter(u=>u.id!=='direct').map(u=>[u.id,u.label])]})}${field('quantityUnitId','Quantity measured in',{options:[['','Same as rate unit'],['sqft','Sq Ft (rate per SQ)']]})}${field('multiplier','Positive multiplier',{value:'1',extra:'inputmode="decimal"'})}${field('customUnit','Custom unit label (optional)',{extra:'maxlength="80"'})}</div></details>`}
function formPage(){if(!flow)return addHome();let t=flow;const names={purchase:'Bought materials',payment:'Paid someone',labour:'Labour or work',other:'Other expense',bill:'Received a bill',plan:'Plan a payment',contract:'Contract & instalments',allocate:'Apply an advance',note:'Work log / timer'};let base=`<div class="page-head"><div><button class="btn link" data-flow="">← All entry types</button><h1>${names[t]}</h1><p>Enter the details, then review before saving.</p></div></div>`,f='';
const vendor=()=>field('vendor','Supplier / person',{required:true,placeholder:'Name of supplier or worker'});
const status=()=>field('payStatus','Payment status',{options:[['unpaid','Not yet paid'],['full','Paid in full'],['partial','Partly paid']]});
const proof=()=>field('proof','Attach bills / files (optional)',{type:'file',full:true,extra:'accept="*/*" multiple'})+field('camera','Take photo with camera (optional)',{type:'file',full:true,extra:'accept="image/*" capture="environment"',hint:'On supported phones, this opens the camera. Photos remain attached to this entry.'});
if(t==='purchase'){f=`<div class="field full"><label>Items — enter amount directly or calculate using quantity × rate</label><div id="items">${itemFields(0)}</div>${substageDataList()}<button class="btn small" type="button" data-action="add-line">+ Add another item</button></div>`+vendor()+field('invoice','Bill number (optional)')+dateField()+workField()+field('place','Where used?',{placeholder:'Sump, ground floor, kitchen...'})+`<details class="field full"><summary class="extras-title">Extra charges (optional) — transport, tax, discount</summary><div class="grid-form">`+field('extras','Transport / unloading (₹)',{type:'number',value:'0',extra:'min="0" step="0.01"'})+field('tax','Tax (₹)',{type:'number',value:'0',extra:'min="0" step="0.01"'})+field('discount','Discount (₹)',{type:'number',value:'0',extra:'min="0" step="0.01"'})+`</div></details>`+status()+field('paidAmount','Amount paid now, if partial (₹)',{type:'number',extra:'min="0" step="0.01"'})+field('method','How paid?',{options:['UPI','Bank transfer','Cash','Cheque']})+field('notes','Notes',{type:'textarea',full:true})+proof()}
else if(t==='payment'){let open=state.bills.filter(b=>dueForBill(state,b.id)>0);f=field('billId','What is this payment for?',{options:[['','Advance / no existing bill'],...open.map(b=>[b.id,`${b.vendor} — ${b.title} · Due ${displayMoney(dueForBill(state,b.id))}`])],full:true})+vendor()+amountField('Money paid (₹)')+field('method','Payment method',{options:['UPI','Bank transfer','Cash','Cheque']})+field('reference','Payment reference (optional)')+dateField()+field('planId','Related planned instalment (optional)',{options:[['','No linked plan'],...state.plans.filter(p=>!p.cancelled&&dueForPlan(state,p.id)>0).map(p=>[p.id,`${p.title} — ${displayMoney(dueForPlan(state,p.id))} remaining`])],full:true})+field('notes','Notes',{type:'textarea',full:true})+proof()}
else if(t==='labour'||t==='other'||t==='bill'){f=amountField(t==='bill'?'Bill amount (INR)':'Total cost (INR)')+field('title',t==='bill'?'What was billed?':t==='labour'?'Work performed':'Purpose',{required:true})+`<div class="field full">${classificationFields()}</div>`+vendor()+dateField()+workField()+field('substage','Substage / work package (optional)',{placeholder:'e.g. Reinforcement, bathroom fittings'})+field('place','Location / room (optional)',{extra:'list="room-choices"'})+(t==='labour'?field('wageMode','How to enter wage amount?',{options:[['amount','Enter total directly'],['calculated','Calculate from units × rate']]})+field('qty','Days / hours / units (if calculating)',{type:'number',extra:'min="0.001" step="0.001"'})+field('rate','Rate per unit (₹)',{type:'number',extra:'min="0" step="0.01"'}):'')+advancedCalculationFields()+`<details class="field full"><summary class="extras-title">Extra charges (optional)</summary><div class="grid-form">${field('extras','Transport / unloading (INR)',{type:'number',value:'0',extra:'min="0" step="0.01"'})}${field('tax','Tax (INR)',{type:'number',value:'0',extra:'min="0" step="0.01"'})}${field('discount','Discount (INR)',{type:'number',value:'0',extra:'min="0" step="0.01"'})}</div></details>`+field('invoice','Invoice / reference (optional)')+(t!=='bill'?status()+field('paidAmount','Amount paid now, if partial (₹)',{type:'number',extra:'min="0" step="0.01"'})+field('method','How paid?',{options:['UPI','Bank transfer','Cash','Cheque']}):'')+field('notes','Notes',{type:'textarea',full:true})+proof()}
else if(t==='plan'){f=`<div class="field full">${classificationFields()}</div>`+vendor()+field('title','What is this payment for?',{required:true,placeholder:'Engineer - stage 2'})+amountField('Planned amount (₹)')+field('date','Due date',{type:'date',required:true,value:localDate()})+workField()+field('remind','Remind me',{options:[['0','On due date'],['1','1 day before'],['3','3 days before'],['7','7 days before'],['-1','No reminder']]})+field('notes','Notes',{type:'textarea',full:true})}
else if(t==='contract'){f=`<div class="field full">${classificationFields()}</div>`+vendor()+field('title','Contract name',{required:true,placeholder:'Engineer supervision agreement'})+amountField('Agreed total (\u20b9)')+advancedCalculationFields()+field('count','Number of instalments',{type:'number',value:'16',required:true,extra:'min="1" max="120" step="1"'})+field('date','First due date',{type:'date',value:localDate(),required:true})+field('frequency','Repeat every',{options:[['month','Month'],['week','Week']]})+workField()+field('notes','Agreement notes',{type:'textarea',full:true})}
else if(t==='allocate'){let adv=state.payments.filter(p=>availableForPayment(state,p.id)>0);let open=state.bills.filter(b=>dueForBill(state,b.id)>0);f=field('paymentId','Previously paid advance',{options:adv.map(p=>[p.id,`${p.vendor} · Available ${displayMoney(availableForPayment(state,p.id))}`]),required:true,full:true})+field('billId','Unpaid bill',{options:open.map(b=>[b.id,`${b.vendor} · Due ${displayMoney(dueForBill(state,b.id))}`]),required:true,full:true})+amountField('Advance to apply (₹)');if(!adv.length||!open.length)return base+`<div class="notice">This action requires both an unapplied payment and an unpaid bill. ${btn('add','Create another entry')}</div>`}
else if(t==='note'){f=field('title','Activity / note',{required:true,placeholder:'Site inspection, material count...'})+workField()+field('date','Activity date',{type:'date',value:localDate(),required:true})+field('notes','Details',{type:'textarea',full:true})+`<div class="field full"><label>Stopwatch (optional)</label><div id="clock-wrap" class="card soft"><div class="clock" id="clock-face">00:00:00</div><div class="toolbar">${btn('start-timer','Start','btn')}${btn('stop-timer','Stop','btn')}${btn('reset-timer','Reset','btn')}</div><small class="hint">Recorded duration is a note, not a wage charge.</small><input type="hidden" name="seconds" id="f-seconds" value="0"></div></div>`}
return base+`<datalist id="room-choices">${['Hall','Parking','Bathroom','Kitchen','Bedroom','Staircase','Balcony','Terrace'].map(p=>`<option>${p}</option>`).join('')}</datalist><form id="entry-form" data-form="entry"><div class="card"><div class="grid-form">${f}</div><div class="two-actions"><span class="hint">${t==='plan'||t==='contract'?'Planning does not record a payment.':'You can enter a total directly. Quantity, rate, unit, transport, tax and discount are optional.'}</span><button class="btn primary" type="submit">Review entry →</button></div></div></form>`}
function itemFields(i){return `<div class="line-item" data-line="${i}"><div class="line-grid"><label>Material / item<input class="item-name" placeholder="Steel, bricks, basin, fittings..." required maxlength="140"></label><label>Amount entry<select class="item-mode" aria-label="Amount entry method"><option value="amount">Enter total directly</option><option value="calculated">Quantity × unit rate</option></select></label><label class="item-direct">Item total (₹)<input class="item-amount" inputmode="decimal" type="number" value="0" min="0" step="0.01" aria-label="Direct item amount in rupees"></label><label class="item-more-toggle" style="grid-column:1/-1;display:flex;align-items:center;gap:9px"><input class="item-more-details" type="checkbox" style="width:18px;height:18px"> Add quantity, unit or rate (optional)</label><label class="item-detail hidden">Quantity<input class="item-qty" type="number" step="0.001" min="0" value="0" placeholder="0"></label><label class="item-detail hidden">Unit rate (₹)<input class="item-rate" type="number" step="0.01" min="0" value="0" placeholder="0"></label><label class="item-detail hidden">Unit<select class="item-unit">${unitOptions()}</select></label><label class="item-detail hidden">Quantity measured in<select class="item-quantity-unit"><option value="">Same as rate unit</option><option value="sqft">Sq Ft (rate per SQ)</option></select></label><label class="item-detail hidden">Multiplier (optional)<input class="item-multiplier" inputmode="decimal" value="1" aria-label="Optional positive multiplier"></label><label class="item-detail hidden">Custom unit label<input class="item-custom-unit" maxlength="80"></label></div>${classificationFields()}<div class="line-grid section"><label style="grid-column:span 2">Work stage<select class="item-work"><option value="">Use overall category</option>${stageOptions().map(w=>`<option>${escapeHTML(w)}</option>`).join('')}</select></label><label style="grid-column:span 2">Substage / work package (optional)<input class="item-substage" list="stage-substage-choices" maxlength="120" placeholder="e.g. Reinforcement, sump base, pillar"></label><label style="grid-column:span 2">Location / room (optional)<input class="item-place" list="room-choices" placeholder="Sump wall, kitchen..."></label></div>${i?'<button class="btn small" type="button" data-action="remove-line">Remove item</button>':''}</div>`}
function updateEntryOptionalFields(){if(!$('entry-form'))return;for(const row of $('entry-form').querySelectorAll('[data-line]')){const calculated=row.querySelector('.item-mode')?.value==='calculated';const extra=row.querySelector('.item-more-details')?.checked;row.querySelector('.item-more-toggle')?.classList.toggle('hidden',calculated);for(const item of row.querySelectorAll('.item-detail'))item.classList.toggle('hidden',!calculated&&!extra);row.querySelector('.item-direct')?.classList.toggle('hidden',calculated);for(const css of ['.item-qty','.item-rate']){const input=row.querySelector(css);if(input)input.required=calculated;}}const status=$('f-payStatus')?.value;let paid=$('f-paidAmount')?.closest('.field');if(paid)paid.classList.toggle('hidden',status!=='partial');let method=$('f-method')?.closest('.field');if(method&&flow!=='payment')method.classList.toggle('hidden',status==='unpaid');const wage=$('f-calculate')?.value==='calculated'?'amount':$('f-wageMode')?.value;if(flow==='labour'&&wage){for(const css of ['qty','rate']){let el=$('f-'+css);el?.closest('.field')?.classList.toggle('hidden',wage!=='calculated');if(el)el.required=wage==='calculated'}$('f-amount')?.closest('.field')?.classList.toggle('hidden',wage==='calculated');if($('f-amount'))$('f-amount').required=wage!=='calculated'&&$('f-calculate')?.value!=='calculated';}}

function formData(form){return Object.fromEntries(new FormData(form).entries())}function requiredStr(v,name){if(!String(v||'').trim())throw Error('Please enter '+name+'.');return String(v).trim()}
function prepareEntry(form){const t=flow,v=formData(form),date=v.date;if(v.calculate==='calculated'){v.amount=inputMoney(lineTotal(v.calcQty,v.calcRate,{multiplier:v.multiplier||'1',unitId:v.unitId||null,quantityUnitId:v.quantityUnitId}));v.wageMode='amount'}if(date&&!validDate(date))throw Error('Choose a valid date.');if(t==='note'){return {kind:t,title:requiredStr(v.title,'the activity'),work:v.work,notes:v.notes,seconds:Number(v.seconds||0),date:v.date}}if(t==='allocate')return{kind:t,billId:v.billId,paymentId:v.paymentId,amount:paise(v.amount)};if(t==='payment'){const amount=paise(v.amount);if(amount<=0)throw Error('Enter a payment above ₹0.');let bill=state.bills.find(b=>b.id===v.billId),plan=state.plans.find(p=>p.id===v.planId);return {kind:t,amount,vendor:bill?.vendor||requiredStr(v.vendor,'recipient'),billId:v.billId||'',planId:v.planId||'',method:v.method,reference:v.reference,date:v.date,notes:v.notes,files:[...(form.querySelector('input[name=proof]')?.files||[]),...(form.querySelector('input[name=camera]')?.files||[])]}}
if(t==='plan'||t==='contract'){const amount=paise(v.amount);if(amount<=0)throw Error('Enter an amount above ₹0.');return {...readClassification(form),...(v.calculate==='calculated'?{calculation:{mode:'calculated',qty:v.calcQty,rate:v.calcRate,unitId:v.unitId||null,quantityUnitId:v.quantityUnitId||null,multiplier:v.multiplier||'1',unit:v.customUnit||UNITS.find(u=>u.id===v.unitId)?.label||''}}:{}),kind:t,vendor:requiredStr(v.vendor,'recipient'),title:requiredStr(v.title,'purpose'),amount,date,work:v.work,notes:v.notes,remind:Number(v.remind||0),count:Number(v.count),frequency:v.frequency}}
let total,lines=[];if(t==='purchase'){let loc=v.work||'';lines=[...form.querySelectorAll('[data-line]')].map(row=>{let calculated=row.querySelector('.item-mode').value==='calculated';return {...readClassification(row),unitId:row.querySelector('.item-unit').value||null,quantityUnitId:row.querySelector('.item-quantity-unit').value||null,multiplier:calculated?(row.querySelector('.item-multiplier').value||'1'):'1',label:requiredStr(row.querySelector('.item-name').value,'material name'),mode:calculated?'calculated':'amount',...(calculated?{qty:row.querySelector('.item-qty').value,rate:row.querySelector('.item-rate').value,unit:row.querySelector('.item-custom-unit').value||UNITS.find(u=>u.id===row.querySelector('.item-unit').value)?.label||row.querySelector('.item-unit').value}:{directAmountPaise:paise(row.querySelector('.item-amount').value||'0'),qty:(row.querySelector('.item-more-details').checked&&Number(row.querySelector('.item-qty').value)>0)?row.querySelector('.item-qty').value:null,rate:(row.querySelector('.item-more-details').checked&&Number(row.querySelector('.item-rate').value)>0)?row.querySelector('.item-rate').value:null,unit:row.querySelector('.item-more-details').checked?(row.querySelector('.item-custom-unit').value||UNITS.find(u=>u.id===row.querySelector('.item-unit').value)?.label||null):null}),work:row.querySelector('.item-work').value||loc,substage:(row.querySelector('.item-substage')?.value||'').trim().slice(0,120),place:row.querySelector('.item-place').value||v.place||'Unspecified'}});const extras=paise(v.extras||'0'),tax=paise(v.tax||'0'),discount=paise(v.discount||'0');total=billTotal(lines,extras,tax,discount);if(total<=0)throw Error('Bill total must be more than ₹0.');v.extrasPaise=extras;v.taxPaise=tax;v.discountPaise=discount}
else if(t==='labour'){const detailed=v.wageMode==='calculated';total=detailed?lineTotal(v.qty,v.rate):paise(v.amount);lines=[detailed?{label:v.title,qty:v.qty,rate:v.rate,unit:'Work unit',work:v.work,substage:v.substage||'',place:v.place||'Unspecified',mode:'calculated'}:{label:v.title,mode:'amount',directAmountPaise:total,qty:null,rate:null,unit:null,work:v.work,substage:v.substage||'',place:v.place||'Unspecified'}];if(total<=0)throw Error('Labour amount must be more than ₹0.')}else{total=paise(v.amount);if(total<=0)throw Error('Enter an amount above ₹0.');lines=[{label:v.title,mode:'amount',directAmountPaise:total,qty:null,rate:null,unit:null,work:v.work,substage:v.substage||'',place:v.place||'Unspecified'}]}
if(t!=='purchase'&&v.calculate==='calculated'){total=lineTotal(v.calcQty,v.calcRate,{multiplier:v.multiplier||'1',unitId:v.unitId||null,quantityUnitId:v.quantityUnitId});if(total<=0)throw Error('Calculated cost must be positive');lines=[{label:v.title,mode:'calculated',qty:v.calcQty,rate:v.calcRate,unit:v.customUnit||UNITS.find(u=>u.id===v.unitId)?.label||'',unitId:v.unitId||null,quantityUnitId:v.quantityUnitId||null,multiplier:v.multiplier||'1',work:v.work,substage:v.substage||'',place:v.place||'Unspecified'}]}if(t!=='purchase'){lines=lines.map(l=>({...l,...readClassification(form)}));v.extrasPaise=paise(v.extras||'0');v.taxPaise=paise(v.tax||'0');v.discountPaise=paise(v.discount||'0');total=billTotal(lines,v.extrasPaise,v.taxPaise,v.discountPaise);if(total<=0)throw Error('Bill total must be positive')}let paid=0;if(t!=='bill'){if(v.payStatus==='full')paid=total;else if(v.payStatus==='partial'){paid=paise(v.paidAmount);if(paid<=0||paid>=total)throw Error('Partial payment must be above ₹0 and less than the total bill.')}}return {...readClassification(form),kind:t,vendor:requiredStr(v.vendor,'supplier / person'),title:t==='purchase'?lines.map(l=>l.label).join(', ').slice(0,120):requiredStr(v.title,'purpose'),date,work:v.work,substage:v.substage||'',place:v.place,invoice:v.invoice,notes:v.notes,lines,total,paid,method:v.method,extras:v.extrasPaise||0,tax:v.taxPaise||0,discount:v.discountPaise||0,files:[...(form.querySelector('input[name=proof]')?.files||[]),...(form.querySelector('input[name=camera]')?.files||[])]}}
function calculationLabel(l){const quantityUnit=UNITS.find(u=>u.id===l.quantityUnitId)?.label||l.unit||'',rateUnit=UNITS.find(u=>u.id===l.unitId)?.label||l.unit||'';return `${l.qty} ${quantityUnit}${l.quantityUnitId==='sqft'&&l.unitId==='sq100'?' / 100':''} x INR ${l.rate} per ${rateUnit||'unit'} x multiplier ${l.multiplier||'1'}`}
function reviewModal(data){let labels=[['Entry type',({purchase:'Bought materials',payment:'Paid someone',labour:'Labour or work',other:'Other expense',bill:'Received a bill',plan:'Plan a payment',contract:'Contract & instalments',allocate:'Apply an advance',note:'Work log / timer'})[data.kind]],['Recipient',data.vendor||'—'],['Purpose',data.title||'—'],['Date',data.date||localDate()],['Amount',Number.isSafeInteger(data.amount)?displayMoney(data.amount):Number.isSafeInteger(data.total)?displayMoney(data.total):'—'],['Paid now',data.paid?displayMoney(data.paid):data.kind==='payment'?displayMoney(data.amount):'Nothing']];if(data.kind==='payment'){const bill=state.bills.find(b=>b.id===data.billId),plan=state.plans.find(p=>p.id===data.planId);if(bill){const due=dueForBill(state,bill.id);labels.push(['Linked original bill',bill.title+' / '+bill.vendor],['Bill balance before payment',displayMoney(due)],['Bill balance after payment',displayMoney(due-data.amount)])}if(plan){const remaining=dueForPlan(state,plan.id);labels.push(['Linked planned instalment',plan.title+' / '+plan.vendor],['Planned amount before payment',displayMoney(remaining)],['Planned amount after payment',displayMoney(remaining-data.amount)])}}if(data.kind==='contract')labels.push(['Agreed commitment',displayMoney(data.amount)],['Planned instalments',String(data.count)],['Recorded bill cost','No actual bill created']);if(data.calculation)labels.push(['Agreement calculation',calculationLabel(data.calculation)]);if(data.lines){for(const l of data.lines)labels.push(['Cost classification',categoryPath(l,costCatalog(state)).join(' > ')+(l.costNature?' / '+l.costNature:'')],['Item amount',displayMoney(lineValue(l))+(l.mode==='calculated'?' / '+calculationLabel(l):' / Direct amount')]);labels.push(['Freight',displayMoney(data.extras||0)],['Tax',displayMoney(data.tax||0)],['Discount',displayMoney(data.discount||0)],['Remaining due',displayMoney(data.total-(data.paid||0))]);if(data.extras&&data.lines.some(l=>/transport|freight|unload/i.test(l.label)))labels.push(['Check transport','Transport appears in an item and invoice extras. Confirm these are separate charges.'])}const impact=data.kind==='payment'?'Money paid increases. Any selected bill or instalment balance reduces; the cost is not counted again.':data.kind==='plan'||data.kind==='contract'?'Adds planned instalments only. No cash or expense is posted.':data.kind==='allocate'?'Applies money already paid to a bill; cash paid does not increase.':data.kind==='note'?'Adds an activity record only. No money is changed.':`Records a bill/cost of ${displayMoney(data.total)}. ${data.paid?'Also records a linked payment of '+displayMoney(data.paid)+'.':'Money paid stays unchanged.'}`;openModal(`<div class="modal-title"><h2>Check before saving</h2>${btn('close','×','modal-close')}</div><p class="mini">Review these details carefully. Edits and deletions are recorded in Change logs.</p>${labels.map(([k,v])=>`<div class="kv"><span>${k}</span><strong>${escapeHTML(v)}</strong></div>`).join('')}<p class="notice" style="margin-top:14px"><b>What this changes:</b> ${escapeHTML(impact)}</p><div class="actions right section">${btn('close','Back to edit','btn')}${btn('confirm','Confirm entry','btn primary')}</div>`);pending=data}
let pending=null,isPosting=false;async function fileInputToObject(file,category,linkId='',meta={}){if(!file)return null;if(file.size>250*1024*1024)throw Error('A single file exceeds the 250 MB web-app import limit. Keep large CAD files in a dedicated document system.');const data=await file.arrayBuffer(),hash=Array.from(new Uint8Array(await crypto.subtle.digest('SHA-256',data))).map(x=>x.toString(16).padStart(2,'0')).join('');let id=uid(),model={id,name:file.name||'Attachment',type:file.type||'application/octet-stream',size:file.size,sha256:hash,category,work:meta.work||'',place:meta.place||'',status:meta.status||'Received',revision:meta.revision||'R0',notes:meta.notes||'',linkId,importedAt:new Date().toISOString(),parentId:meta.parentId||null};return {metadata:model,stored:{id,blob:new Blob([data],{type:model.type})}}}
function addAudit(st,type,description,linked=''){st.audit.push({id:uid(),type,description,linked,at:new Date().toISOString()})}
async function confirmEntry(){if(!pending||isPosting)return;isPosting=true;const d=pending;try{let proofs=[];for(const f of (d.files||[])){proofs.push(await fileInputToObject(f,'Bills and proof','',{work:d.work}))}let savedId='';await commit(st=>{const stamp=new Date().toISOString();if(d.kind==='note'){let e={id:uid(),kind:'note',title:d.title,work:d.work,notes:d.notes,date:d.date,seconds:d.seconds,recordedAt:stamp,status:'Saved'};st.entries.push(e);savedId=e.id}
else if(d.kind==='plan'){const p={...readClassificationData(d),id:uid(),vendor:d.vendor,title:d.title,amount:d.amount,due:d.date,work:d.work,notes:d.notes,remind:d.remind,recordedAt:stamp,cancelled:false};st.plans.push(p);savedId=p.id}
else if(d.kind==='contract'){if(!Number.isInteger(d.count)||d.count<1||d.count>120)throw Error('Instalments must be between 1 and 120.');if(d.amount<d.count)throw Error('Each instalment must be at least one paise.');const c={...readClassificationData(d),scheduleComplete:true,calculation:d.calculation||null,work:d.work,id:uid(),vendor:d.vendor,title:d.title,amount:d.amount,count:d.count,notes:d.notes,createdAt:stamp};st.contracts.push(c);let base=Math.floor(d.amount/d.count),remain=d.amount%d.count;for(let i=0;i<d.count;i++){let dt=new Date(d.date+'T12:00:00');if(d.frequency==='week')dt.setDate(dt.getDate()+7*i);else {const day=dt.getDate();dt.setDate(1);dt.setMonth(dt.getMonth()+i);const last=new Date(dt.getFullYear(),dt.getMonth()+1,0).getDate();dt.setDate(Math.min(day,last))}const due=localDate(dt);st.plans.push({...readClassificationData(d),id:uid(),contractId:c.id,title:`${d.title} · Instalment ${i+1}/${d.count}`,vendor:d.vendor,amount:base+(i<remain?1:0),due,work:d.work,recordedAt:stamp,cancelled:false,remind:3})}savedId=c.id}
else if(d.kind==='allocate'){const p=st.payments.find(x=>x.id===d.paymentId),b=st.bills.find(x=>x.id===d.billId);if(!p||!b)throw Error('Selected record no longer exists.');if(p.vendor.trim().toLowerCase()!==b.vendor.trim().toLowerCase())throw Error('Advance recipient differs from bill supplier.');let avail=availableForPayment(st,p.id),due=dueForBill(st,b.id);if(d.amount>avail||d.amount>due||d.amount<=0)throw Error('Amount exceeds the available advance or invoice due.');st.allocations.push({id:uid(),paymentId:p.id,billId:b.id,amount:d.amount,recordedAt:stamp});savedId=b.id}
else if(d.kind==='payment'){let p={id:uid(),vendor:d.vendor,amount:d.amount,date:d.date,recordedAt:stamp,method:d.method,reference:d.reference||'',planId:d.planId||'',notes:d.notes||''};let alloc=d.billId?{id:uid(),paymentId:p.id,billId:d.billId,amount:p.amount,recordedAt:stamp}:null;checkNewPayment(st,p,alloc);st.payments.push(p);if(alloc)st.allocations.push(alloc);savedId=p.id}
else{const b={...readClassificationData(d),id:uid(),date:d.date,title:d.title,vendor:d.vendor,work:d.work,substage:d.substage||'',place:d.place,invoice:d.invoice,notes:d.notes,type:d.kind,recordedAt:stamp,total:d.total,lines:d.lines.map(l=>({...l,value:lineValue(l)})),extras:d.extras,tax:d.tax,discount:d.discount};st.bills.push(b);savedId=b.id;if(d.paid){const p={id:uid(),vendor:d.vendor,amount:d.paid,date:d.date,recordedAt:stamp,method:d.method,reference:'',notes:'Paid at purchase'};st.payments.push(p);st.allocations.push({id:uid(),paymentId:p.id,billId:b.id,amount:d.paid,recordedAt:stamp})}}
for(const proof of proofs){proof.metadata.linkId=savedId;st.files.push(proof.metadata)}addAudit(st,'entry_added',`${d.kind} recorded`,savedId)},{newFiles:proofs.map(x=>x.stored)});closeModal();pending=null;toast('Entry saved successfully');goto('activity')}catch(e){toast(e.message,true)}finally{isPosting=false}}
function activity(){const ev=eventList(state).filter(e=>(activityFilter==='All'||e.kind===activityFilter)&&(!activityFrom||e.date>=activityFrom)&&(!activityTo||e.date<=activityTo)&&[e.label,e.party,e.status,e.work,e.date].some(v=>String(v||'').toLowerCase().includes(activitySearch.toLowerCase())));return `${heading('Activity','Search the complete history of payments, bills, plans, files and work logs.',btn('export-csv','Export CSV','btn'))}<div class="filter-row"><input class="search" id="activity-search" aria-label="Search activity" placeholder="Search vendor, bill, activity..." value="${escapeHTML(activitySearch)}"><select id="activity-filter" aria-label="Filter activities">${[['All','All activity'],['bill','Bills and purchases'],['payment','Payments'],['plan','Planned payments'],['file','Files'],['note','Work log'],['contract','Contracts'],['audit','Change logs'],['allocation','Advance allocations']].map(([x,y])=>`<option value="${x}" ${activityFilter===x?'selected':''}>${y}</option>`).join('')}</select><input type="date" id="activity-from" aria-label="From date" title="From date" value="${escapeHTML(activityFrom)}"><input type="date" id="activity-to" aria-label="To date" title="To date" value="${escapeHTML(activityTo)}"></div><div class="list">${activityRows(ev.slice(0,150))}</div>${ev.length>150?'<p class="info-note">Showing the 150 most recent matching entries. Refine your search to see older ones.</p>':''}`}
function filesPage(){const docs=state.files.filter(f=>(fileFilter==='All'||f.category===fileFilter)&&[f.name,f.notes,f.work,f.place,f.revision,f.status,f.category].some(v=>String(v||'').toLowerCase().includes(fileSearch.toLowerCase()))).sort((a,b)=>new Date(b.importedAt)-new Date(a.importedAt));return `${heading('Project Files','Drawings, CAD, bills, photos and agreements—all in one place.',`<div class="actions">${btn('backup','Backup & Restore','btn')}${btn('import-files','+ Add files','btn primary')}</div>`)}<div class="notice">Original documents are stored in your project vault (private SQLite database when signed in, or browser storage in optional local-only mode). All file formats can be stored; previews depend on browser support. Export a verified encrypted backup periodically and store it separately from the project database.</div><div class="filter-row"><input id="file-search" class="search" placeholder="Find drawings, bills or suppliers..." aria-label="Search files" value="${escapeHTML(fileSearch)}"><select id="file-filter" aria-label="Document category"><option value="All">All files</option>${fileCategories.map(c=>`<option ${fileFilter===c?'selected':''}>${escapeHTML(c)}</option>`).join('')}</select></div><div class="card"><div class="section-head"><h2>Saved documents</h2><span class="mini">${docs.length} of ${state.files.length}</span></div><div class="list">${docs.length?docs.map(f=>`<button class="list-row" data-file="${f.id}"><span class="file-row"><span class="file-icon">${escapeHTML((f.name.split('.').pop()||'FILE').slice(0,4).toUpperCase())}</span><span class="file-desc"><strong>${escapeHTML(f.name)}</strong><small>${escapeHTML(f.category)} · ${escapeHTML(f.revision)} · ${escapeHTML(f.status)}</small><small>${new Date(f.importedAt).toLocaleDateString('en-IN')} · ${humanSize(f.size)}</small></span></span><span class="btn small">View →</span></button>`).join(''):`<div class="empty"><strong>No files found</strong>Add drawings, photos, receipts, CAD files or documents of any format.</div>`}</div></div>`}
let fileSearch='';function humanSize(n){if(n<1024)return n+' B';if(n<1024**2)return(n/1024).toFixed(1)+' KB';return(n/1024**2).toFixed(1)+' MB'}
function fileForm(action='import',metadata=null){const f=metadata;return `<div class="modal-title"><h2>${action==='edit'?'Edit file details':action==='revision'?'Add new revision':'Add files to project'}</h2>${btn('close','×','modal-close')}</div><form data-form="file" data-mode="${action}" data-id="${f?.id||''}"><div class="grid-form">${action!=='edit'?field('file','Choose document / photo / CAD file',{type:'file',required:true,full:true,extra:'accept="*/*"'}):''}${field('category','Document category',{options:fileCategories.map(c=>[c,c]),value:f?.category||fileCategories[0]})}${field('status','Drawing / file status',{options:['Received','For review','Approved for construction','Superseded','Archived'],value:action==='revision'?'For review':f?.status||'Received'})}${field('revision','Revision label',{value:action==='revision'?nextRevision(f?.revision):f?.revision||'R0'})}${field('work','Related work',{options:[['','Not linked'],...workOptions.map(w=>[w,w])],value:f?.work||''})}${field('place','Floor / room / area',{value:f?.place||''})}${field('linkId','Related invoice (optional)',{options:[['','Not linked'],...state.bills.map(b=>[b.id,`${b.vendor} · ${b.title}`])],value:f?.linkId||''})}${field('notes','Description / notes',{type:'textarea',full:true})}</div><p class="notice" style="margin:14px 0">The original document is preserved. Editing its contents outside the app should produce a new revision, not overwrite old evidence.</p><div class="actions right">${btn('close','Cancel') }<button class="btn primary" type="submit">${action==='edit'?'Save details':'Save document'}</button></div></form>`}
function nextRevision(r='R0'){const num=Number((r||'R0').match(/\d+/)?.[0]||0);return 'R'+(num+1)}
async function saveFiles(form){if(isPosting)return;isPosting=true;const mode=form.dataset.mode,id=form.dataset.id,formObj=formData(form);let meta0=state.files.find(f=>f.id===id);try{if(mode==='edit'){await commit(st=>{const f=st.files.find(x=>x.id===id);if(!f)throw Error('File not found');f.category=formObj.category;f.status=formObj.status;f.revision=String(formObj.revision||'R0').slice(0,40);f.work=formObj.work;f.place=formObj.place;f.linkId=formObj.linkId;f.notes=formObj.notes;addAudit(st,'file_metadata','Updated metadata',f.id)});closeModal();toast('File information saved');return}const files=[...form.querySelector('input[name=file]').files];if(!files.length)throw Error('Choose a file.');const items=[];for(const f of files){const o=await fileInputToObject(f,formObj.category,formObj.linkId,{status:formObj.status,work:formObj.work,place:formObj.place,revision:formObj.revision,notes:formObj.notes,parentId:mode==='revision'?(meta0.parentId||meta0.id):null});items.push(o)}await commit(st=>{for(const it of items){st.files.push(it.metadata);addAudit(st,'file_import','Imported file',it.metadata.id)}},{newFiles:items.map(o=>o.stored)});closeModal();toast('Document saved with original file');goto('files')}catch(e){toast(e.message,true)}finally{isPosting=false}}
async function importManyFiles(fileList){const incoming=[...fileList];if(!incoming.length)return;try{const objects=[];for(const f of incoming)objects.push(await fileInputToObject(f,guessCategory(f.name)));await commit(st=>{for(const it of objects){st.files.push(it.metadata);addAudit(st,'file_import',it.metadata.name,it.metadata.id)}},{newFiles:objects.map(x=>x.stored)});toast(`${objects.length} file(s) saved`);goto('files')}catch(e){toast(e.message,true)}}
function guessCategory(name){const x=name.split('.').pop()?.toLowerCase();return ['dwg','dxf','ifc','rvt','dgn','skp'].includes(x)?'Survey / CAD':['jpg','jpeg','png','webp','gif','heic','bmp','avif'].includes(x)?'Site photographs':['pdf'].includes(x)?'Miscellaneous':'Miscellaneous'}
let modalFocus=null;function openModal(html){closeModal();modalFocus=document.activeElement;$('modal-inner').innerHTML=html;$('modal').hidden=false;$('modal-inner').scrollTop=0;$('modal-inner').querySelector('input,button,select,textarea')?.focus()}function closeModal(){if(modalURL){URL.revokeObjectURL(modalURL);modalURL=null}$('modal').hidden=true;$('modal-inner').innerHTML='';if(modalFocus?.isConnected)modalFocus.focus();modalFocus=null}
function browserPreviewable(meta){const ext=(meta.name.split('.').pop()||'').toLowerCase();const type=(meta.type||'').toLowerCase();return ['pdf','png','jpg','jpeg','webp','gif','bmp','avif','txt','csv','json','md','xml','log','mp3','wav','ogg','mp4','webm'].includes(ext)||/^(application\/pdf|image\/(png|jpeg|gif|webp|bmp)|text\/plain|audio\/(mpeg|ogg|wav)|video\/(mp4|webm))$/.test(type)}
async function documentDetail(id){let f=state.files.find(x=>x.id===id);if(!f)return toast('File not found',true);openModal(`<div class="modal-title"><h2>Document details</h2>${btn('close','×','modal-close')}</div><div class="card soft"><h3>${escapeHTML(f.name)}</h3><p class="mini">${escapeHTML(f.category)} · ${escapeHTML(f.revision)} · <span class="tag ${f.status==='Approved for construction'?'good':f.status==='Superseded'?'bad':'warn'}">${escapeHTML(f.status)}</span></p></div><div class="actions section">${btn('view-file','👁 View','btn primary',`data-id="${id}"`)}${browserPreviewable(f)?btn('open-file-tab','Open in new tab','btn',`data-id="${id}"`):''}${btn('external-file','Share with app','btn',`data-id="${id}"`)}${btn('download-file','Save a copy','btn',`data-id="${id}"`)}${btn('edit-file','Edit details','btn',`data-id="${id}"`)}${btn('revise-file','New revision','btn',`data-id="${id}"`)}${btn('delete-file','Delete file','btn danger',`data-id="${id}"`)}</div><div id="document-preview" class="section"></div><div class="section"><div class="kv"><span>Imported</span><strong>${localStamp(f.importedAt)}</strong></div><div class="kv"><span>File type</span><strong>${escapeHTML(f.type)}</strong></div><div class="kv"><span>Size</span><strong>${humanSize(f.size)}</strong></div><div class="kv"><span>Related work</span><strong>${escapeHTML(f.work||'Not linked')}</strong></div><div class="kv"><span>Room / location</span><strong>${escapeHTML(f.place||'Not linked')}</strong></div><div class="kv"><span>Notes</span><strong>${escapeHTML(f.notes||'—')}</strong></div></div>`)}
async function previewFile(id){const meta=state.files.find(x=>x.id===id),o=await readFile(id);if(!o?.blob)return toast('Original file missing. Restore from backup.',true);const el=$('document-preview');if(!el)return;el.replaceChildren();if(modalURL)URL.revokeObjectURL(modalURL);modalURL=URL.createObjectURL(o.blob);const ext=meta.name.split('.').pop()?.toLowerCase(),mime=o.blob.type;let child;if(mime.startsWith('image/')||['jpg','png','jpeg','webp','gif','bmp','avif'].includes(ext)){child=document.createElement('img');child.src=modalURL;child.alt=meta.name}else if(mime==='application/pdf'||ext==='pdf'){child=document.createElement('iframe');URL.revokeObjectURL(modalURL);modalURL=URL.createObjectURL(new Blob([o.blob],{type:'application/pdf'}));child.src=modalURL;child.title='PDF preview: '+meta.name;child.setAttribute('loading','eager')}else if(mime.startsWith('video/')||['mp4','webm','mov'].includes(ext)){child=document.createElement('video');child.src=modalURL;child.controls=true}else if(mime.startsWith('audio/')||['mp3','wav','ogg'].includes(ext)){child=document.createElement('audio');child.src=modalURL;child.controls=true}else if(mime.startsWith('text/')||['txt','csv','json','xml','md','log','svg'].includes(ext)){child=document.createElement('pre');child.textContent=(await o.blob.slice(0,500000).text()).slice(0,100000)}else{el.innerHTML='<div class="notice">This file is safely stored in its original format. This browser cannot preview it. Use Share with app on a supported device, or Save a copy to open it with compatible CAD or Office software.</div>';return}let box=document.createElement('div');box.className='preview';box.appendChild(child);el.appendChild(box)}
async function downloadFile(id){const meta=state.files.find(x=>x.id===id),o=await readFile(id);if(!meta||!o)throw Error('Original file missing');downloadBlob(o.blob,meta.name)}
async function openFileTab(id){const meta=state.files.find(x=>x.id===id);if(!meta)throw Error('Document no longer exists');if(!browserPreviewable(meta)){toast('This format cannot be opened inside a normal browser. Use Share with app on a supported device, or explicitly Save a copy to open it in specialist software.',true);return;}const tab=window.open('about:blank','_blank');if(!tab){toast('Allow pop-ups to open a new document tab, or use View inside BuildLedger.',true);return}try{const o=await readFile(id);if(!o?.blob)throw Error('Original document not found.');const blob=new Blob([o.blob],{type:previewType(meta,o.blob)});const url=URL.createObjectURL(blob);tab.location.replace(url);setTimeout(()=>URL.revokeObjectURL(url),120000)}catch(e){tab.close();throw e}}
function previewType(meta,blob){const x=meta.name.split('.').pop()?.toLowerCase()||'';return x==='pdf'?'application/pdf':({jpg:'image/jpeg',jpeg:'image/jpeg',png:'image/png',webp:'image/webp',gif:'image/gif',txt:'text/plain',csv:'text/plain',md:'text/plain',json:'text/plain'})[x]||blob.type||'application/octet-stream'}
async function shareFile(id){const meta=state.files.find(x=>x.id===id),o=await readFile(id);if(!meta||!o)throw Error('Original file missing');const f=new File([o.blob],meta.name,{type:previewType(meta,o.blob)});if(navigator.canShare?.({files:[f]})){try{await navigator.share({title:meta.name,files:[f]});return}catch(e){if(e.name==='AbortError')return;throw e}}toast('This browser does not support sharing files to installed apps. Use View for supported formats, or explicitly Save a copy to open in another program. No automatic download was started.',true)}
async function deleteDocument(id){const doc=state.files.find(f=>f.id===id);if(!doc)throw Error('This document was already deleted');const connected=doc.linkId?' It is linked to a financial record; its original will no longer be available as evidence.':'';if(!confirm(`Delete ${doc.name} and its original file permanently?${connected} This cannot be undone except by restoring an earlier backup.`))return;await commit(st=>{const f=st.files.find(x=>x.id===id);if(!f)throw Error('File no longer exists');st.files=st.files.filter(x=>x.id!==id);addAudit(st,'file_delete','Deleted document '+f.name,id)},{removeFiles:[id]});closeModal();toast('Document removed from project and active storage');goto('files')}


function hierarchyControls(){
 const controls=[['all','All stages'],['sub','Stage'],['item','Substage'],['source','Material']];
 return `<nav aria-label="Construction cost breadcrumb" class="h-breadcrumb">${controls.slice(0,hierarchyPath.length+1).map(([k,name],i)=>`<button class="h-crumb ${i===hierarchyPath.length?'current':''}" data-hpath="${encodeURIComponent(JSON.stringify(hierarchyPath.slice(0,i)))}" aria-current="${i===hierarchyPath.length?'page':'false'}">${i===0?'All stages':escapeHTML(hierarchyPath[i-1])}</button>`).join('<span class="h-chevron" aria-hidden="true">›</span>')}</nav>`
}
function hierarchyView(){
 const hierarchy=buildHierarchy(state),selected=hierarchySummary(hierarchy,hierarchyPath);
 if(!selected){hierarchyPath=[];return hierarchyView()}
 const depth=hierarchyPath.length,levels=['Stage','Substage','Material','Source entries'];
 const children=selected.children;
 const visible=children.slice(0,hierarchyLimit);
 const total=selected.total;
 const sourceCount=selected.count;
 const pct=n=>total?(100*n/total).toFixed(1):'0.0';
 const rows=visible.map((c,i)=>{
 const next=hierarchyPath.concat(c.name);
 return `<button class="h-row" type="button" data-hpath="${encodeURIComponent(JSON.stringify(next))}" aria-label="Open ${escapeHTML(c.name)}, ${displayMoney(c.total)}, ${pct(c.total)} percent of parent"><span class="h-row-top"><span class="h-row-name"><span class="h-dot" style="background:${colors[i%colors.length]}"></span>${escapeHTML(c.name)}</span><span class="h-row-number">${displayMoney(c.total)}</span></span><span class="h-row-bottom"><span class="h-track"><span class="h-fill" style="width:${pct(c.total)}%;background:${colors[i%colors.length]}"></span></span><small>${pct(c.total)}% · ${c.count} bill${c.count===1?'':'s'}</small><span class="h-arrow">›</span></span></button>`
 }).join('');
 const billRows=selected.entries.slice(0,hierarchyLimit).map(e=>`<button class="list-row" data-detail="bill:${escapeHTML(e.billId)}" type="button"><span style="min-width:0"><strong>${escapeHTML(e.billTitle)}</strong><small>${escapeHTML(e.vendor)} · ${escapeHTML(e.lineLabel)} · ${escapeHTML(e.date)}</small></span><span class="amount">${displayMoney(e.amount)}</span></button>`).join('');
 const numItems=depth===3?selected.entries.length:children.length;
 const remaining=numItems-hierarchyLimit;
 return `<section class="card hierarchy-panel"><div class="section-head"><div><h2>Construction cost explorer</h2><p class="mini">Select a stage to see its substages, materials, and original bills.</p></div>${btn('manage-categories','+ Categories','btn small')}</div>${hierarchyControls()}<div class="h-meta"><div><small>${depth===0?'All recorded costs':levels[depth-1]}</small><strong>${escapeHTML(depth?hierarchyPath[depth-1]:'Entire project')}</strong></div><div class="h-grand"><span>${displayMoney(total)}</span><small>${sourceCount} related bill${sourceCount===1?'':'s'} · Posted bills only</small></div></div>${total===0?'<div class="empty"><strong>No recorded costs</strong>Add your first material or work bill to see the hierarchy.</div>':depth<3?`<div class="h-level"><strong>${levels[depth]} breakdown</strong><small>Tap to go one level deeper</small></div><div class="h-rows">${rows}</div>`:`<div class="h-level"><strong>Original bill entries</strong><small>Open a bill to inspect its full details</small></div><div class="list">${billRows}</div>`}${remaining>0?`<div class="h-more">${btn('hierarchy-more',`Show ${Math.min(30,remaining)} more (${remaining} hidden)`,'btn small')}</div>`:''}<p class="info-note">Totals include proportional freight, tax and discount allocations; no invoice is counted twice. Older records without a substage remain under “Not specified”.</p></section>`
}
function manageCategoryModal(){if(categoryMode==='work'){const existing=customCatalog();return `<div class="modal-title"><h2>Manage work categories</h2>${btn('close','?','modal-close')}</div><div class="filter-row">${btn('category-cost','Cost Heads')}${btn('category-work','Work Stages','btn primary')}</div><form data-form="category"><div class="grid-form">${field('category-stage','Stage',{required:true})}${field('category-substage','Substage',{required:true})}</div><button class="btn primary section" type="submit">Add category</button></form>${existing.map(c=>`<div class="kv"><span>${escapeHTML(c.stage)}</span><strong>${escapeHTML(c.substage)}</strong></div>`).join('')}`}
const catalog=costCatalog(state),filtered=catalog.filter(n=>(n.label+' '+(n.aliases||[]).join(' ')).toLowerCase().includes(categorySearch.toLowerCase()));return `<div class="modal-title"><h2>Manage cost categories</h2>${btn('close','?','modal-close')}</div><div class="filter-row">${btn('category-cost','Cost Heads','btn primary')}${btn('category-work','Work Stages')}</div><p class="mini">Rename, reorder or archive categories. Historical classification stays linked to its stable identity. Changes are audited.</p><form data-form="cost-category"><div class="grid-form">${field('cost-label','New category label',{required:true,extra:'maxlength="140"'})}${field('cost-parent','Parent',{options:[['','New cost head'],...catalog.filter(n=>n.type!=='detail'&&n.active!==false).map(n=>[n.id,(n.type==='head'?'Head: ':'Subhead: ')+n.label])]})}</div><button class="btn primary section" type="submit">Add category</button></form><div class="filter-row"><input id="cost-category-search" type="search" value="${escapeHTML(categorySearch)}" placeholder="Search categories" aria-label="Search cost categories"></div><div class="h-category-list">${filtered.map(n=>`<form data-form="cost-category-edit" data-id="${escapeHTML(n.id)}" class="cost-manage-row"><label><span class="mini">${escapeHTML(n.type)}${n.parentId?' ? '+escapeHTML(catalog.find(p=>p.id===n.parentId)?.label||''):''} ? ${state.bills.filter(b=>(b.lines?.length?b.lines:[b]).some(l=>[l.costHeadId,l.costSubheadId,l.costDetailId].includes(n.id))).length} bills</span><input name="label" aria-label="Category label" value="${escapeHTML(n.label)}" maxlength="140" required></label><label>Order<input name="order" aria-label="Display order" type="number" min="0" step="1" value="${n.order||0}" required></label><label><input name="active" type="checkbox" ${n.active!==false?'checked':''}> Active</label><button class="btn small" type="submit">Save</button></form>`).join('')||'<div class="empty">No matching categories.</div>'}</div>`}
function costView(){const tree=buildCostHierarchy(state),node=costHierarchySummary(tree,costPath);if(!node){const catalog=costCatalog(state),id=costPath.at(-1);if(catalog.some(n=>n.id===id)){return `<section class="card hierarchy-panel"><h2>Cost head explorer</h2><button class="btn" data-cost-path="${encodeURIComponent('[]')}">All cost heads</button><h3>${escapeHTML(catalog.find(n=>n.id===id).label)}</h3><p class="mini">No recorded bills under this category.</p>${relatedCostPlans()}</section>`}costPath=[];return costView()}const children=(node.children||[]).filter(n=>n.name.toLowerCase().includes(costSearch.toLowerCase())),depth=costPath.length;return `<section class="card hierarchy-panel"><div class="section-head"><div><h2>Cost head explorer</h2><p class="mini">Cost Head ? Subhead ? Item / Service ? Original Bill</p></div>${btn('manage-categories','Categories','btn small')}</div><nav class="h-breadcrumb" aria-label="Cost head breadcrumb"><button class="h-crumb" data-cost-path="${encodeURIComponent('[]')}">All cost heads</button>${costPath.map((id,i)=>`<button class="h-crumb" data-cost-path="${encodeURIComponent(JSON.stringify(costPath.slice(0,i+1)))}">${escapeHTML(costCatalog(state).find(n=>n.id===id)?.label||'Unclassified / Legacy')}</button>`).join('')}</nav><div class="h-meta"><strong>${displayMoney(node.total)}</strong><span>Recorded bill cost ? Payments and plans excluded</span></div><div class="filter-row"><input id="cost-search" type="search" value="${escapeHTML(costSearch)}" aria-label="Filter cost groups" placeholder="Filter this level"></div>${depth<3?`<div class="h-rows">${children.slice(0,hierarchyLimit).map(n=>`<button class="h-row" data-cost-path="${encodeURIComponent(JSON.stringify([...costPath,n.id]))}"><span class="h-row-top"><strong>${escapeHTML(n.name)}</strong><strong>${displayMoney(n.total)}</strong></span><small>${node.total?(100*n.total/node.total).toFixed(1):'0'}% ? ${n.count||0} source entries</small></button>`).join('')}</div>`:`<div class="list">${(node.entries||[]).filter(e=>[e.lineLabel,e.billTitle,e.vendor,e.work,e.place].join(' ').toLowerCase().includes(costSearch.toLowerCase())).slice(0,hierarchyLimit).map(e=>{const bill=state.bills.find(b=>b.id===e.billId);return `<button class="list-row" data-detail="bill:${escapeHTML(e.billId)}"><span><strong>${escapeHTML(bill?.title||e.lineLabel)}</strong><small>${escapeHTML(bill?.vendor||'')} / ${escapeHTML(e.work||'No stage')} / ${escapeHTML(e.place||'No location')} / Bill unpaid ${displayMoney(bill?dueForBill(state,bill.id):0)}</small></span><strong>${displayMoney(e.amount)}</strong></button>`}).join('')}</div>`}${(depth<3?children.length:(node.entries||[]).length)>hierarchyLimit?btn('hierarchy-more','Show more','btn section'):''}${!node.total?'<div class="empty"><strong>No recorded costs</strong>Add a bill or classify an existing bill.</div>':''}${costPath.length?relatedCostPlans():`<div class="section"><h3>Planned payments and agreements</h3><p class="mini">Select a cost head to inspect future instalments independently of recorded bills.</p><div class="filter-row">${[...new Set([...state.plans.filter(p=>!p.cancelled&&dueForPlan(state,p.id)>0),...state.contracts].map(r=>r.costHeadId).filter(Boolean))].map(id=>`<button class="btn" data-cost-path="${encodeURIComponent(JSON.stringify([id]))}">${escapeHTML(costCatalog(state).find(n=>n.id===id)?.label||'Unclassified / Legacy')}</button>`).join('')||'<p class="mini">No classified upcoming payments or agreements.</p>'}</div></div>`}</section>`}
function relatedCostPlans(){const match=r=>costPath.every((id,i)=>(r[['costHeadId','costSubheadId','costDetailId'][i]]||['legacy-head','legacy-subhead','legacy-detail'][i])===id);const plans=state.plans.filter(p=>match(p)&&!p.cancelled&&dueForPlan(state,p.id)>0),contracts=state.contracts.filter(match);return `<div class="section"><h3>Linked plans and agreements</h3><p class="mini">Future payments and contract commitments are shown separately from recorded bill cost.</p>${plans.map(p=>`<button class="list-row" data-detail="plan:${escapeHTML(p.id)}"><span><strong>${escapeHTML(p.title)}</strong><small>${escapeHTML(p.vendor)} / Planned ${escapeHTML(p.due)}</small></span><strong>${displayMoney(dueForPlan(state,p.id))}</strong></button>`).join('')}${contracts.map(c=>`<button class="list-row" data-detail="contract:${escapeHTML(c.id)}"><span><strong>${escapeHTML(c.title)}</strong><small>Agreed commitment / ${escapeHTML(c.vendor)}</small></span><strong>${displayMoney(c.amount)}</strong></button>`).join('')}${!plans.length&&!contracts.length?'<p class="mini">No linked future instalments or contracts.</p>':''}</div>`}
function explore(){
 const x=summary(state);
 return `${heading('Cost explorer','A clear path from project totals to the original invoice.',btn('calendar','Payment calendar'))}<div class="filter-row">${[['cost','Cost Heads'],['nature','Cost Nature'],['hierarchy','Stages & materials'],['work','Work stage'],['place','Location'],['vendor','Supplier'],['material','Material'],['calendar','Calendar']].map(([key,label])=>`<button class="seg ${selectedView===key?'active':''}" data-view="${key}">${label}</button>`).join('')}</div>${selectedView==='calendar'?renderCalendar():selectedView==='cost'?costView():selectedView==='nature'?`<section class="card"><h2>Cost by nature</h2>${costBars('nature')}</section>`:selectedView==='hierarchy'?hierarchyView():`<div class="card"><div class="section-head"><div><span class="eyebrow">RECORDED BILL COSTS</span><h2>Cost distribution</h2></div><span class="tag">${displayMoney(x.invoiced)} total</span></div>${segmentDonut(selectedView)}</div><div class="two section"><section class="card"><div class="section-head"><h2>Category ranking</h2><span class="tag">All categories</span></div>${workBars(selectedView,true)}</section><section class="card"><div class="section-head"><h2>At a glance</h2></div>${segmentSnapshot(selectedView)}<div class="sep"></div>${[['Recorded cost',x.invoiced],['Money paid',x.paid],['Outstanding bills',x.owed],['Unapplied advances',x.advances]].map(([k,v])=>`<div class="kv"><span>${k}</span><strong>${displayMoney(v)}</strong></div>`).join('')}</section></div><section class="card section"><div class="section-head"><h2>Payments over time</h2>${btn('export-csv','Export records','btn small')}</div>${monthlyChart()}</section>`}`;
}
function monthlyChart(){
 const arr=monthlyTotals(state,12);if(!arr.length)return '<div class="empty chart-empty"><strong>Your cash flow starts here</strong>Record a payment to see your monthly trend.</div>';
 const max=Math.max(...arr.map(r=>r.value));
 return `<div class="cash-chart" role="img" aria-label="Monthly payments: ${escapeHTML(arr.map(r=>r.month+' '+displayMoney(r.value)).join('; '))}">${arr.map(row=>`<div class="cash-column"><span class="cash-value">${displayMoney(row.value)}</span><div class="cash-plot"><span class="cash-bar" style="height:${Math.max(2,row.value/max*100)}%" title="${escapeHTML(row.month)}: ${displayMoney(row.value)}"></span></div><span class="cash-month">${escapeHTML(new Date(row.month+'-01T12:00:00').toLocaleDateString('en-IN',{month:'short',year:'2-digit'}))}</span></div>`).join('')}</div>`;
}
function calendarEvents(iso){return [...state.plans.filter(p=>!p.cancelled&&p.due===iso).map(p=>({label:p.title,type:'plan',amount:dueForPlan(state,p.id),id:p.id})),...state.bills.filter(b=>b.date===iso).map(b=>({label:b.title,type:'bill',amount:b.total,id:b.id})),...state.payments.filter(p=>p.date===iso).map(p=>({label:'Paid '+p.vendor,type:'payment',amount:p.amount,id:p.id})),...state.entries.filter(e=>e.date===iso).map(e=>({label:e.title,type:'note',amount:null,id:e.id}))]}
function renderCalendar(){const first=new Date(year,month,1),days=new Date(year,month+1,0).getDate(),start=(first.getDay()+6)%7,weekday=['Mon','Tue','Wed','Thu','Fri','Sat','Sun'];let cells=Array.from({length:start},()=>'<div class="cal-day empty-cal" aria-hidden="true"></div>');for(let d=1;d<=days;d++){let iso=`${year}-${String(month+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`,events=calendarEvents(iso);cells.push(`<button class="cal-day ${calendarDay===iso?'active':''}" data-date="${iso}"><strong>${d}</strong>${events.length?`<span class="pills"><i class="cal-dot"></i><small>${events.length} event${events.length>1?'s':''}</small></span>`:''}</button>`)}const list=calendarEvents(calendarDay);return `<div class="two"><section class="card"><div class="section-head"><div class="toolbar">${btn('prev-month','←','btn small')}<h2>${new Date(year,month,1).toLocaleDateString('en-IN',{month:'long',year:'numeric'})}</h2>${btn('next-month','→','btn small')}</div></div><div class="calendar-grid">${weekday.map(x=>`<div class="cal-head">${x}</div>`).join('')}${cells.join('')}</div></section><section class="card"><div class="section-head"><h2>${new Date(calendarDay+'T12:00:00').toLocaleDateString('en-IN',{day:'numeric',month:'short',year:'numeric'})}</h2>${btn('new-plan','+ Plan','btn small')}</div><div class="list">${list.length?list.map(e=>`<button class="list-row" data-detail="${e.type}:${e.id}"><span><strong>${escapeHTML(e.label)}</strong><small>${e.type==='plan'?'Scheduled, not paid':e.type==='payment'?'Payment made':'Recorded'}</small></span><span class="amount">${e.amount!=null?displayMoney(e.amount):'—'}</span></button>`).join(''):'<div class="empty">No records for this date.</div>'}</div></section></div><div class="card section"><div class="section-head"><h2>Upcoming scheduled payments</h2>${btn('notifications','Enable reminders','btn small')}</div><p class="mini">In-browser alerts work while the app is open. Background notifications after closing the website require an additional push service.</p><div class="list" style="margin-top:12px">${state.plans.filter(p=>!p.cancelled&&dueForPlan(state,p.id)>0).sort((a,b)=>a.due.localeCompare(b.due)).slice(0,30).map(p=>`<button class="list-row" data-detail="plan:${p.id}"><span><strong>${escapeHTML(p.title)}</strong><small>${escapeHTML(p.vendor)} · Due ${escapeHTML(p.due)}</small></span><span class="amount">${displayMoney(dueForPlan(state,p.id))}</span></button>`).join('')||'<div class="empty">No payments scheduled.</div>'}</div></div>`}
