function csv(){function cell(x){let s=String(x??'');if(/^[\s]*[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}const columns=['Record Type','Date','Source ID','Supplier','Description','Cost Head','Subhead','Item / Service','Cost Nature','Work Stage','Work Substage','Location','Quantity','Unit','Unit Rate INR','Multiplier','Recorded Cost INR','Payment Cash Outflow INR','Bill Outstanding INR','Planned Amount INR','Contract Commitment INR','Bill Amount Settled INR','Audit Evidence','Recorded at','Reference','Payment / Plan Status'];const rows=[];const classification=r=>{const path=categoryPath(r,costCatalog(state));return {'Cost Head':path[0],'Subhead':path[1],'Item / Service':path[2],'Cost Nature':r.costNature||'','Work Stage':r.work||'','Work Substage':r.substage||'','Location':r.place||''}};const bills=new Map(state.bills.map(b=>[b.id,b]));for(const e of allocatedCostLines(state)){const b=bills.get(e.billId),l=b.lines?.[e.lineIndex]||b;rows.push({'Record Type':'Bill line','Date':b.date,'Source ID':b.id,'Supplier':b.vendor,'Description':l.label||b.title,'Recorded at':b.recordedAt,'Reference':b.invoice,...classification({...l,work:l.work||b.work,substage:l.substage||b.substage,place:l.place||b.place}),'Quantity':l.qty??'','Unit':l.unit||UNITS.find(u=>u.id===l.unitId)?.label||'','Unit Rate INR':l.rate??'','Multiplier':l.multiplier??'','Recorded Cost INR':inputMoney(e.amount)})}for(const b of state.bills)rows.push({'Record Type':'Bill settlement','Date':b.date,'Source ID':b.id,'Supplier':b.vendor,'Description':b.title,'Recorded at':b.recordedAt,'Reference':b.invoice,'Bill Outstanding INR':inputMoney(dueForBill(state,b.id)),'Bill Amount Settled INR':inputMoney(b.total-dueForBill(state,b.id))});for(const p of state.payments)rows.push({'Record Type':'Payment','Date':p.date,'Source ID':p.id,'Supplier':p.vendor,'Description':p.notes||'Payment','Recorded at':p.recordedAt,'Reference':p.reference,'Payment / Plan Status':'Posted','Payment Cash Outflow INR':inputMoney(p.amount)});for(const p of state.plans)rows.push({'Record Type':'Plan','Date':p.due,'Source ID':p.id,'Supplier':p.vendor,'Description':p.title,'Recorded at':p.recordedAt,'Reference':p.contractId,'Payment / Plan Status':p.cancelled?'Cancelled':'Active',...classification(p),'Planned Amount INR':inputMoney(p.cancelled?0:dueForPlan(state,p.id))});for(const c of state.contracts)rows.push({'Record Type':'Contract','Date':c.createdAt?.slice(0,10),'Source ID':c.id,'Supplier':c.vendor,'Description':c.title,'Recorded at':c.createdAt,'Reference':c.id,...classification(c),'Contract Commitment INR':inputMoney(c.amount)});for(const a of state.audit)rows.push({'Record Type':'Audit','Date':a.at?.slice(0,10),'Source ID':a.id,'Description':a.description||a.type,'Audit Evidence':JSON.stringify(a.changes||a.catalogChanges||{before:a.before,after:a.after})});downloadBlob(new Blob(['\uFEFF',[columns,...rows.map(row=>columns.map(c=>row[c]??''))].map(r=>r.map(cell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'}),'BuildLedger_Records_'+localDate()+'.csv')}
function details(kind,id){let html='',x=kind==='bill'?state.bills.find(x=>x.id===id):kind==='payment'?state.payments.find(x=>x.id===id):kind==='plan'?state.plans.find(x=>x.id===id):kind==='file'?state.files.find(x=>x.id===id):kind==='audit'?state.audit.find(x=>x.id===id):kind==='contract'?state.contracts.find(x=>x.id===id):kind==='allocation'?state.allocations.find(x=>x.id===id):state.entries.find(x=>x.id===id);if(!x)return toast('Record not found',true);if(kind==='file')return documentDetail(id);if(kind==='audit')return auditDetail(id);let rows=[];if(kind==='bill'){rows=[['Recorded cost',displayMoney(x.total)],['Supplier',x.vendor],['Work',x.work],['Location',x.place],['Invoice',x.invoice||'—'],['Occurred on',x.date],['Recorded at',localStamp(x.recordedAt)],['Payments applied to this bill',displayMoney(x.total-dueForBill(state,x.id))],['Still to pay',displayMoney(dueForBill(state,x.id))]];rows.push(['Cost classification',x.lines?.length>1?'See classified invoice items':categoryPath(x.lines?.[0]||x,costCatalog(state)).join(' > ')]);html=x.lines?.length?`<div class="card soft section"><h3>Bill items</h3>${x.lines.map(l=>`<div class="kv"><span>${escapeHTML(l.label)}<small>${escapeHTML(categoryPath(l,costCatalog(state)).join(' > '))} / ${escapeHTML(l.costNature||'Not specified')}<br>${escapeHTML(l.mode==='calculated'||(l.qty!=null&&l.mode!=='amount')?calculationLabel(l):'Direct amount')}<br>Stage: ${escapeHTML(l.work||x.work||'Not specified')} / ${escapeHTML(l.substage||'Not specified')}<br>Location: ${escapeHTML(l.place||x.place||'Not specified')}</small></span><strong>${displayMoney(l.value)}</strong></div>`).join('')}</div>`:'';}
else if(kind==='payment'){rows=[['Money paid',displayMoney(x.amount)],['Paid to',x.vendor],['Method',x.method],['Payment date',x.date],['Recorded at',localStamp(x.recordedAt)],['Reference',x.reference||'—'],['Unapplied advance',displayMoney(availableForPayment(state,x.id))]]}
else if(kind==='plan'){rows=[['Planned amount',displayMoney(x.amount)],['Paid against plan',displayMoney(x.amount-dueForPlan(state,x.id))],['Still planned',displayMoney(dueForPlan(state,x.id))],['Recipient',x.vendor],['Due date',x.due],['Recorded at',localStamp(x.recordedAt)],['Remind',x.remind>=0?x.remind+' days before':'Off'],['Status',x.cancelled?'Cancelled':'Active']]}
else if(kind==='allocation'){rows=[['Amount applied',displayMoney(x.amount)],['Payment',state.payments.find(p=>p.id===x.paymentId)?.vendor||x.paymentId],['Bill',state.bills.find(b=>b.id===x.billId)?.title||x.billId],['Recorded',localStamp(x.recordedAt)]]}
else if(kind==='contract'){rows=[['Calculation',x.calculation?calculationLabel(x.calculation):'Direct agreed amount'],['Contract',x.title],['Recipient',x.vendor],['Agreed total',displayMoney(x.amount)],['Instalments',x.count],['Created',localStamp(x.createdAt)],['Notes',x.notes||'?']]}
else rows=[['Title',x.title],['Date',x.date],['Recorded',localStamp(x.recordedAt)],['Notes',x.notes||'—'],['Timer',x.seconds?Math.round(x.seconds/60)+' minutes':'—']];
if(['plan','contract'].includes(kind))rows.push(['Cost classification',categoryPath(x,costCatalog(state)).join(' > ')],['Cost nature',x.costNature||'Not specified']);openModal(`<div class="modal-title"><h2>${kind==='bill'?'Bill details':kind==='payment'?'Payment details':kind==='plan'?'Planned payment':kind==='contract'?'Contract details':kind==='allocation'?'Advance allocation':'Work log'}</h2>${btn('close','×','modal-close')}</div>${rows.map(([key,val])=>`<div class="kv"><span>${escapeHTML(key)}</span><strong>${escapeHTML(val)}</strong></div>`).join('')}${html}<div class="actions section">${kind==='bill'&&dueForBill(state,x.id)>0?btn('pay-bill','Record payment','btn primary',`data-id="${x.id}"`):''}${kind==='plan'&&!x.cancelled&&dueForPlan(state,x.id)>0?btn('pay-plan','Record payment','btn primary',`data-id="${x.id}"`):''}${kind==='plan'&&!x.cancelled?btn('cancel-plan','Cancel planned payment','btn danger',`data-id="${x.id}"`):''}${btn('edit-entry','Edit','btn',`data-kind="${kind}" data-id="${escapeHTML(x.id)}"`)}${btn('delete-entry','Delete','btn danger',`data-kind="${kind}" data-id="${escapeHTML(x.id)}"`)}${btn('close','Close')}</div>`)}
function entryRecord(kind,id){return entryRecordFrom(state,kind,id)}
function auditDetail(id){
 const log=state.audit.find(a=>a.id===id);if(!log)return toast('Log not found',true);
 const labels={title:'Title',vendor:'Recipient',amount:'Amount',total:'Bill total',date:'Date',due:'Due date',notes:'Notes',method:'Payment method',reference:'Reference',work:'Stage',substage:'Substage',place:'Location',invoice:'Invoice',lines:'Bill items',extras:'Extra charges',tax:'Tax',discount:'Discount',cancelled:'Cancelled',remind:'Reminder days',planId:'Payment plan',paymentId:'Payment',billId:'Bill',costHeadId:'Cost head',costSubheadId:'Cost subhead',costDetailId:'Cost item / service',costNature:'Cost nature',unitId:'Rate unit',quantityUnitId:'Quantity unit',multiplier:'Multiplier'};
 let catalogChanges='';if(log.type==='cost_catalog'){const before=new Map((log.catalogChanges?log.catalogChanges.filter(c=>c.before).map(c=>c.before):log.before||[]).map(n=>[n.id,n])),after=new Map((log.catalogChanges?log.catalogChanges.filter(c=>c.after).map(c=>c.after):log.after||[]).map(n=>[n.id,n]));const changed=[...new Set([...before.keys(),...after.keys()])].filter(id=>JSON.stringify(before.get(id))!==JSON.stringify(after.get(id)));const describe=n=>n?`${n.label} [${n.id}] / ${n.type} / parent ${n.parentId||'root'} / order ${n.order} / ${n.active?'Active':'Inactive'}${n.description?' / '+n.description:''}${n.suggestedUnit?' / Unit '+n.suggestedUnit:''}${n.aliases?.length?' / Aliases '+n.aliases.join(', '):''}`:'Absent';catalogChanges=`<div class="change-table"><div class="change-head"><span>Category</span><span>Before</span><span>After</span></div>${changed.map(id=>`<div class="change-row"><span>${escapeHTML(id)}</span><span>${escapeHTML(describe(before.get(id)))}</span><span>${escapeHTML(describe(after.get(id)))}</span></div>`).join('')}</div>`}
 const text=(key,value)=>{
  if(value===undefined||value===null||value==='')return '\u2014';
  if(['amount','total','extras','tax','discount'].includes(key))return displayMoney(value);
  if(key==='lines')return value.map(l=>(l.label||'Item')+': '+displayMoney(l.value)+' / '+categoryPath(l,costCatalog(state)).join(' > ')+' ['+[l.costHeadId,l.costSubheadId,l.costDetailId].filter(Boolean).join(', ')+'] / '+(l.costNature||'Not specified')+' / '+(l.mode==='calculated'?calculationLabel(l):'Direct amount')).join('; ');if(['costHeadId','costSubheadId','costDetailId'].includes(key))return (costCatalog(state).find(n=>n.id===value)?.label||'Historical category')+' ['+value+']';if(['unitId','quantityUnitId'].includes(key))return UNITS.find(u=>u.id===value)?.label||value;
  if(key==='planId')return state.plans.find(p=>p.id===value)?.title||'Previously linked plan';
  if(key==='billId')return state.bills.find(b=>b.id===value)?.title||'Previously linked bill';
  if(key==='paymentId')return state.payments.find(p=>p.id===value)?.vendor||'Previously linked payment';
  return String(value);
 };
 openModal(`<div class="modal-title"><h2>Change log</h2>${btn('close','\u00d7','modal-close')}</div><p class="notice">${escapeHTML(log.description||log.type)}</p><p class="mini">${escapeHTML(localStamp(log.at))}</p>${catalogChanges}${(log.changes||[]).map(c=>{
  const fields=Object.keys(labels).filter(k=>(k in c.before||c.after&&k in c.after)&&(!c.after||JSON.stringify(c.before[k])!==JSON.stringify(c.after[k])));
  return `<section class="section"><h3>${escapeHTML(c.before.title||c.before.vendor||c.kind)}</h3><div class="change-table"><div class="change-head"><span>Field</span><span>Before</span><span>After</span></div>${fields.map(k=>`<div class="change-row"><span>${labels[k]}</span><span>${escapeHTML(text(k,c.before[k]))}</span><span>${c.after?escapeHTML(text(k,c.after[k])):'Deleted'}</span></div>`).join('')}</div></section>`;
 }).join('')||(catalogChanges?'':'<p class="mini">This historical log contains a description only.</p>')}`);
}
function editEntryForm(kind,id){
 const r=entryRecord(kind,id);if(!r)return toast('Entry not found',true);
 let fields=['bill','plan','contract'].includes(kind)?`<div class="field full">${classificationFields(r)}</div>`:'';fields+=!['payment','allocation'].includes(kind)?field('title','Title',{value:r.title,required:true,full:true}):'';
 if(!['note','allocation'].includes(kind))fields+=field('vendor','Supplier / recipient',{value:r.vendor,required:true});
 if(!['contract','allocation'].includes(kind))fields+=field('date',kind==='plan'?'Due date':'Date',{type:'date',value:r.due||r.date||localDate(),required:true});
 if(['payment','plan','contract','allocation'].includes(kind))fields+=field('amount','Amount (\u20b9)',{type:'number',value:inputMoney(r.amount),required:true,extra:'min="0.01" step="0.01"'});
 if(!['payment','allocation'].includes(kind))fields+=field('work','Work stage',{value:r.work||''});
 if(kind==='bill'){
  fields+=field('substage','Substage',{value:r.substage||''})+field('place','Location',{value:r.place||''})+field('invoice','Invoice / reference',{value:r.invoice||''});
  if(r.lines?.length)fields+=`<div class="field full"><h3>Bill items</h3>${r.lines.map(l=>`<div class="edit-line grid-form section">${classificationFields(l)}<label>Material<input name="line-label" value="${escapeHTML(l.label)}" required></label><label>Amount (\u20b9)<input name="line-amount" type="number" min="0" step="0.01" value="${inputMoney(l.value)}" required></label><label>Stage<input name="line-work" value="${escapeHTML(l.work||r.work||'')}"></label><label>Substage<input name="line-substage" value="${escapeHTML(l.substage||'')}"></label><label>Location<input name="line-place" value="${escapeHTML(l.place||r.place||'')}"></label></div>`).join('')}</div>`+['extras','tax','discount'].map(k=>field(k,{extras:'Transport / extras (\u20b9)',tax:'Tax (\u20b9)',discount:'Discount (\u20b9)'}[k],{type:'number',value:inputMoney(r[k]||0),extra:'min="0" step="0.01"',required:true})).join('');
  else fields+=field('total','Bill total (\u20b9)',{type:'number',value:inputMoney(r.total),required:true,extra:'min="0.01" step="0.01"'});
 }
 if(kind==='payment')fields+=field('method','Method',{value:r.method||''})+field('reference','Reference',{value:r.reference||''});
 if(kind==='plan')fields+=field('remind','Reminder days before',{type:'number',value:r.remind??-1,extra:'min="-1" max="365" step="1"'});
 fields+=field('notes','Notes',{type:'textarea',full:true});
 openModal(`<div class="modal-title"><h2>Edit ${escapeHTML(kind==='note'?'work log':kind)}</h2>${btn('close','\u00d7','modal-close')}</div><p class="notice">Totals update when saved. Previous values remain in Change logs. Linked payments must still reconcile.${kind==='contract'?' Existing instalment dates stay the same; the new total is spread across them.':''}</p><form data-form="edit-entry" data-kind="${kind}" data-id="${escapeHTML(id)}"><div class="grid-form">${fields}</div><div class="actions right section">${btn('close','Cancel')}<button type="submit" class="btn primary">Save changes</button></div></form>`);
 $('f-notes').value=r.notes||'';
}
async function saveEntryEdit(form){
 if(isPosting)return;isPosting=true;
 try{
  const kind=form.dataset.kind,id=form.dataset.id,v=formData(form),original=structuredClone(entryRecord(kind,id));if(!original)throw Error('Entry no longer exists');
  const patch={notes:v.notes||'',...(['bill','plan','contract'].includes(kind)?readClassification(form):{})};
  if(!['payment','allocation'].includes(kind))patch.title=requiredStr(v.title,'title');
  if(!['note','allocation'].includes(kind))patch.vendor=requiredStr(v.vendor,'recipient');
  if(!['contract','allocation'].includes(kind)){if(!validDate(v.date))throw Error('Choose a valid date');patch[kind==='plan'?'due':'date']=v.date;}
  if(['payment','plan','contract','allocation'].includes(kind)){patch.amount=paise(v.amount);if(kind==='contract'&&patch.amount!==original.amount)patch.calculation=null;if(!patch.amount)throw Error('Amount must be positive');}
  if(!['payment','allocation'].includes(kind))patch.work=v.work;
  if(kind==='bill'){
   Object.assign(patch,{substage:v.substage,place:v.place,invoice:v.invoice});
   const rows=[...form.querySelectorAll('.edit-line')];
   if(rows.length){patch.lines=rows.map((row,i)=>{const amount=paise(row.querySelector('[name="line-amount"]').value);return {...original.lines[i],...readClassification(row),...(amount===lineValue(original.lines[i])?{}:{mode:'amount',directAmountPaise:amount,value:amount,multiplier:null,quantityUnitId:null}),label:requiredStr(row.querySelector('[name="line-label"]').value,'material'),work:row.querySelector('[name="line-work"]').value,substage:row.querySelector('[name="line-substage"]').value,place:row.querySelector('[name="line-place"]').value}});for(const k of ['extras','tax','discount'])patch[k]=paise(v[k]);}
   else patch.total=paise(v.total);
  }
  if(kind==='payment')Object.assign(patch,{method:v.method,reference:v.reference});
  if(kind==='plan'){patch.remind=Number(v.remind);if(!Number.isInteger(patch.remind)||patch.remind< -1||patch.remind>365)throw Error('Invalid reminder');}
  await commit(st=>{if(JSON.stringify(entryRecordFrom(st,kind,id))!==JSON.stringify(original))throw Error('This entry changed. Reopen it before editing.');changeEntry(st,kind,id,patch)});
  closeModal();toast('Entry updated. Previous values saved in Change logs.');
 }finally{isPosting=false}
}
function entryRecordFrom(st,kind,id){return st[{bill:'bills',payment:'payments',plan:'plans',contract:'contracts',note:'entries',allocation:'allocations'}[kind]]?.find(r=>r.id===id)}
async function deleteEntry(kind,id){
 if(isPosting)return;const record=entryRecord(kind,id);if(!record)return toast('Entry not found',true);
 const impact=kind==='bill'?'Linked payments stay recorded and become available advances.':kind==='allocation'?'The payment becomes an available advance and the bill balance reopens.':kind==='payment'?'Linked bill and plan balances reopen.':kind==='plan'||kind==='contract'?'Linked payments stay recorded. The payment schedule is removed.':'The work log is removed.';
 if(!confirm(`Delete ${record.title||record.vendor||'this entry'}? ${impact} A permanent change log keeps the previous values. Attached documents remain in Files.`))return;
 isPosting=true;try{const original=JSON.stringify(record);await commit(st=>{if(JSON.stringify(entryRecordFrom(st,kind,id))!==original)throw Error('This entry changed. Reopen it before deleting.');changeEntry(st,kind,id)});closeModal();toast('Entry deleted. Previous values saved in Change logs.')}finally{isPosting=false}
}

function openCalendar(){route='explore';selectedView='calendar';render();window.scrollTo(0,0)}function render(){navHTML();$('main').innerHTML=route==='home'?home():route==='add'?formPage():route==='activity'?activity():route==='files'?filesPage():explore();if(flow==='note')renderClock();if(flow)updateEntryOptionalFields();showPendingSave()}
function prefillBill(id){goto('add');flow='payment';render();const f=$('f-billId'),b=state.bills.find(x=>x.id===id);if(f&&b){f.value=id;$('f-vendor').value=b.vendor;$('f-amount').value=inputMoney(dueForBill(state,id))}}function prefillPlan(id){goto('add');flow='payment';render();const p=state.plans.find(x=>x.id===id);if(p){$('f-planId').value=id;$('f-vendor').value=p.vendor;$('f-amount').value=inputMoney(dueForPlan(state,id))}}
let timerStart=null,timerSeconds=0,timerTick=null;function renderClock(){if(flow!=='note')return;const el=$('clock-face');if(!el)return;const seconds=timerSeconds+(timerStart?Math.floor((Date.now()-timerStart)/1000):0),fmt=n=>String(n).padStart(2,'0');el.textContent=`${fmt(Math.floor(seconds/3600))}:${fmt(Math.floor(seconds/60)%60)}:${fmt(seconds%60)}`;const input=$('f-seconds');if(input)input.value=seconds}function endClock(){if(timerStart){timerSeconds+=Math.floor((Date.now()-timerStart)/1000);timerStart=null}clearInterval(timerTick);renderClock()}
async function refreshFromOtherTab(){try{await refresh()}catch{}}
async function actionClick(e){const cp=e.target.closest('[data-cost-path]');if(cp){costPath=JSON.parse(decodeURIComponent(cp.dataset.costPath));costSearch='';hierarchyLimit=30;render();return}let nav=e.target.closest('[data-nav]'),action=e.target.closest('[data-action]'),fl=e.target.closest('[data-flow]'),detail=e.target.closest('[data-detail]'),doc=e.target.closest('[data-file]'),view=e.target.closest('[data-view]'),drill=e.target.closest('[data-drill]'),date=e.target.closest('[data-date]'),hpath=e.target.closest('[data-hpath]');if(hpath){try{const value=JSON.parse(decodeURIComponent(hpath.dataset.hpath));if(!Array.isArray(value)||value.length>3||value.some(x=>typeof x!=='string'))throw Error('Invalid category path');hierarchyPath=value;hierarchyLimit=30;render()}catch(err){toast(err.message,true)}return}if(nav){if(nav.dataset.filter)activityFilter=nav.dataset.filter;goto(nav.dataset.nav);return}if(fl){flow=fl.dataset.flow||null;render();return}if(detail){const [kind,id]=detail.dataset.detail.split(':');details(kind,id);return}if(doc){await documentDetail(doc.dataset.file);return}if(view){selectedView=view.dataset.view;hierarchyLimit=30;render();return}if(date){calendarDay=date.dataset.date;render();return}if(drill){activityFilter='bill';activitySearch=drill.dataset.value;goto('activity');return}if(!action)return;const key=action.dataset.action,id=action.dataset.id;try{
switch(key){case 'category-cost':categoryMode='cost';openModal(manageCategoryModal());break;case 'category-work':categoryMode='work';openModal(manageCategoryModal());break;case 'retry-save':await retryPendingWrite();pending=null;closeModal();await refresh();toast('Original save verified.');break;case 'close':closeModal();pending=null;break;case 'add':goto('add');break;case 'activity':goto('activity');break;case 'explore':goto('explore');break;case 'calendar':openCalendar();break;case 'new-plan':goto('add');flow='plan';render();break;case 'settings':openModal(settings());break;case 'backup':openModal(backupUI());break;case 'export-csv':csv();break;case 'manage-categories':openModal(manageCategoryModal());break;case 'hierarchy-more':hierarchyLimit+=30;render();break;case 'notifications':if(!('Notification' in window)){toast('Notifications unavailable in this browser',true);break}if(Notification.permission==='granted'){toast('Notifications already enabled');break}if(Notification.permission==='denied'){toast('Notifications are blocked in browser settings',true);break}Notification.requestPermission().then(v=>toast(v==='granted'?'Reminders enabled while app is open':'Notifications were not enabled'));break;case 'add-line':{const container=$('items');const n=container.querySelectorAll('[data-line]').length;container.insertAdjacentHTML('beforeend',itemFields(n));break}case 'remove-line':action.closest('[data-line]')?.remove();break;case 'edit-entry':editEntryForm(action.dataset.kind,id);break;case 'delete-entry':await deleteEntry(action.dataset.kind,id);break;case 'confirm':await confirmEntry();break;case 'pay-bill':closeModal();prefillBill(id);break;case 'pay-plan':closeModal();prefillPlan(id);break;case 'cancel-plan':if(confirm('Cancel this planned instalment? Historical payments will remain unchanged.')){await commit(st=>{let p=st.plans.find(x=>x.id===id);if(p){p.cancelled=true;addAudit(st,'plan_cancel','Cancelled payment plan',id)}});closeModal();toast('Payment plan cancelled');break}break;case 'import-files':{const chooser=document.createElement('input');chooser.type='file';chooser.multiple=true;chooser.accept='*/*';chooser.onchange=()=>importManyFiles(chooser.files);chooser.click();break}case 'view-file':await previewFile(id);break;case 'delete-file':await deleteDocument(id);break;case 'open-file-tab':await openFileTab(id);break;case 'download-file':await downloadFile(id);break;case 'external-file':await shareFile(id);break;case 'edit-file':{const f=state.files.find(x=>x.id===id);openModal(fileForm('edit',f));applyFileDefaults(f);break}case 'revise-file':{const f=state.files.find(x=>x.id===id);openModal(fileForm('revision',f));applyFileDefaults(f);break}case 'prev-month':month--;if(month<0){month=11;year--}render();break;case 'next-month':month++;if(month>11){month=0;year++}render();break;case 'start-timer':if(!timerStart){timerStart=Date.now();timerTick=setInterval(renderClock,900)}break;case 'stop-timer':endClock();break;case 'reset-timer':timerStart=null;timerSeconds=0;clearInterval(timerTick);renderClock();break;
}}catch(err){toast(err.message,true)}}
function applyFileDefaults(f){if(!f)return;for(const k of ['category','status','revision','work','place','linkId','notes']){let el=$('f-'+k);if(el){const revise=$('modal-inner')?.querySelector('[data-mode]')?.dataset.mode==='revision';el.value=k==='revision'&&revise?nextRevision(f.revision):k==='status'&&revise?'For review':f[k]||''}}if($('f-notes'))$('f-notes').value=f.notes||''}
async function formSubmit(e){const form=e.target.closest('form[data-form]');if(!form)return;e.preventDefault();let name=form.dataset.form;try{if(name==='cost-category'||name==='cost-category-edit'){const v=formData(form);await commit(st=>{if(name==='cost-category'){const parent=costCatalog(st).find(n=>n.id===v['cost-parent']);changeCostCategory(st,null,{label:requiredStr(v['cost-label'],'category label'),parentId:parent?.id||null,type:parent?(parent.type==='head'?'subhead':'detail'):'head',order:0,active:true,origin:'user',aliases:[]})}else changeCostCategory(st,form.dataset.id,{label:requiredStr(v.label,'category label'),order:Number(v.order),active:!!v.active})});openModal(manageCategoryModal());toast('Category saved; history preserved')}else if(name==='edit-entry'){await saveEntryEdit(form)}else if(name==='entry'){reviewModal(prepareEntry(form))}else if(name==='category'){const v=formData(form),stage=requiredStr(v['category-stage'],'stage'),sub=requiredStr(v['category-substage'],'substage');if(stage.length>90||sub.length>120)throw Error('Category labels are too long');await commit(st=>{st.settings??={};st.settings.catalog??=[];if(st.settings.catalog.some(c=>c.stage.toLocaleLowerCase()===stage.toLocaleLowerCase()&&c.substage.toLocaleLowerCase()===sub.toLocaleLowerCase()))throw Error('This category already exists');if(st.settings.catalog.length>=500)throw Error('Maximum 500 custom categories reached');st.settings.catalog.push({id:uid(),stage,substage:sub,createdAt:new Date().toISOString()});addAudit(st,'category_added',stage+' → '+sub)});closeModal();toast('Category saved. It is now available for new entries')}else if(name==='file'){await saveFiles(form)}else if(name==='settings'){const obj=formData(form),budget=paise(obj.budget),projectName=requiredStr(obj.name,'project name');await commit(st=>{st.project.name=projectName;st.project.budget=budget;addAudit(st,'settings','Updated project settings')});closeModal();toast('Settings saved')}else if(name==='backup'){const pass=$('backup-pass').value;const status=$('backup-progress');status.textContent='Preparing encrypted backup...';const zip=await createBackup(pass,(i,n)=>{status.textContent=`Protecting file ${i} of ${n}`});downloadBlob(zip,'BuildLedger_Complete_'+localDate()+'.zip');status.textContent=`Download prepared (${humanSize(zip.size)}). Check that the file was saved before deleting any browser data.`;toast('Encrypted backup generated')}else if(name==='restore'){const formObj=formData(form),file=form.querySelector('input[name=backup]').files[0];if(!file)throw Error('Choose a backup ZIP.');if(!confirm('Restore this backup and replace ALL current records and files on this browser? Export a backup of the current data first.'))return;const status=$('backup-progress');status.textContent='Verifying backup and documents...';const result=await restoreBackup(file,formObj.password,(i,n)=>status.textContent=`Validating file ${i} of ${n}`);closeModal();toast(`Restored ${result.recordCount} records and ${result.fileCount} original files`);await refresh()}}
catch(err){toast(err.message,true);const label=$('backup-progress');if(label)label.textContent=err.message}}
function inputEvent(e){if(e.target.id==='cost-category-search'){categorySearch=e.target.value;const position=e.target.selectionStart;openModal(manageCategoryModal());const x=$('cost-category-search');x.focus();x.setSelectionRange(position,position)}if(e.target.id==='cost-search'){costSearch=e.target.value;const position=e.target.selectionStart;render();const x=$('cost-search');x.focus();x.setSelectionRange(position,position)}if(e.target.id==='activity-search'){const pos=e.target.selectionStart;activitySearch=e.target.value;const wrap=$('main');wrap.innerHTML=activity();const input=$('activity-search');input.focus();input.setSelectionRange(pos,pos)}if(e.target.id==='file-search'){const p=e.target.selectionStart;fileSearch=e.target.value;$('main').innerHTML=filesPage();const x=$('file-search');x.focus();x.setSelectionRange(p,p)}}
async function reminderCheck(){const today=localDate(),s=state.plans.filter(p=>!p.cancelled&&dueForPlan(state,p.id)>0&&p.remind>=0);for(const p of s){const notifyDate=new Date(p.due+'T12:00:00');notifyDate.setDate(notifyDate.getDate()-Number(p.remind));const due=localDate(notifyDate);if(due<=today&&!noticeShown.has(p.id+'-'+today)){noticeShown.add(p.id+'-'+today);if(typeof Notification!=='undefined'&&Notification.permission==='granted'&&document.visibilityState==='visible'){new Notification('BuildLedger payment reminder',{body:`${p.title} · ${displayMoney(dueForPlan(state,p.id))} due ${p.due}`})}}}}
function registerListeners(){document.addEventListener('click',actionClick);document.addEventListener('submit',formSubmit);document.addEventListener('input',inputEvent);document.addEventListener('change',e=>{if(e.target.matches('.cost-select'))updateClassification(e.target);if(e.target.id==='f-calculate'){if(flow==='labour')updateEntryOptionalFields();const calculated=e.target.value==='calculated';$('f-amount')?.toggleAttribute('required',!calculated);for(const k of ['calcQty','calcRate'])$('f-'+k)?.toggleAttribute('required',false)}if(e.target.id==='activity-filter'){activityFilter=e.target.value;render()}if(e.target.id==='activity-from'){activityFrom=e.target.value;render()}if(e.target.id==='activity-to'){activityTo=e.target.value;render()}if(e.target.id==='file-filter'){fileFilter=e.target.value;render()}if(e.target.matches('.item-mode,.item-more-details')||e.target.id==='f-payStatus'||e.target.id==='f-wageMode')updateEntryOptionalFields();if(e.target.id==='f-billId'&&flow==='payment'&&e.target.value){const b=state.bills.find(x=>x.id===e.target.value);if(b){$('f-vendor').value=b.vendor;$('f-amount').value=inputMoney(dueForBill(state,b.id))}}});$('modal').addEventListener('click',e=>{if(e.target===$('modal'))closeModal()});document.addEventListener('keydown',e=>{if(e.key==='Escape'){pending=null;closeModal()}if(e.key==='Tab'&&!$('modal').hidden){const controls=[...$('modal-inner').querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled&&x.offsetParent!==null);const first=controls[0],last=controls.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus()}}});try{bc=new BroadcastChannel('buildledger-sync');bc.onmessage=refreshFromOtherTab}catch{}}
async function start(){registerListeners();try{await openDb();await refresh();const foot=document.querySelector('.rail-end p');if(foot)foot.textContent=storageMode()==='remote'?'Local SQLite database':'Stored on this device';navigator.storage?.persist?.().catch(()=>{});if('serviceWorker'in navigator&&location.protocol!=='file:'){navigator.serviceWorker.register('./sw.js').catch(()=>{})}setInterval(()=>reminderCheck().catch(()=>{}),60000);if('Notification'in window)reminderCheck().catch(()=>{})}catch(e){if(e.code==='NOT_SIGNED_IN'){showSignIn();return}$('main').innerHTML=`<div class="card"><h2>Cannot open project data</h2><p class="notice error">${escapeHTML(e.message)}</p><p>Try a modern browser over HTTPS or localhost, and make sure private browsing is disabled.</p></div>`}}
function showSignIn(message=''){ $('main').innerHTML=`<div class="card" style="max-width:480px;margin:60px auto"><h1>Unlock your project</h1><p class="notice">Your records and original documents are protected by the server. Enter your owner password.</p><form id="login-form"><div class="field"><label for="owner-password">Owner password</label><input type="password" id="owner-password" required autocomplete="current-password" minlength="12"></div><p class="notice error" id="login-error">${escapeHTML(message)}</p><div class="actions section"><button class="btn primary" type="submit">Sign in</button></div></form></div>`;$('login-form').addEventListener('submit',async e=>{e.preventDefault();try{await loginRemote($('owner-password').value);await refresh();const foot=document.querySelector('.rail-end p');if(foot)foot.textContent='Protected local database'}catch(err){$('login-error').textContent=err.message}}, {once:false})}
start();
